sections.css:
@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;600;700;800&family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,600;1,8..60,400&display=swap');


/* ═══════════════════════════════════════════
   RESET & ROOT
═══════════════════════════════════════════ */
.lg-sakums *, .lg-sakums .pn-page *::before, .lg-sakums .pn-page *::after { box-sizing: border-box; }
.lg-sakums .pn-page, .lg-sakums .pn-page * { margin: 0; padding: 0; box-sizing: border-box; }
.lg-sakums .pn-page, .lg-sakums .pn-page * { border-right: none !important; }
.lg-sakums .pn-hero-img, .lg-sakums .pn-aktuali, .lg-sakums .pn-about, .lg-sakums .pn-virzieni, .lg-sakums .pn-steam, .lg-sakums .pn-kapec, .lg-sakums .pn-celvedis, .lg-sakums .pn-mediji, .lg-sakums .pn-final-cta { border: none !important; outline: none !important; }

.lg-sakums {
  --green:    #2A5E4A;
  --green-d:  #1e4535;
  --cream:    #FFF8EE;
  --orange:   #FF9068;
  --blue:     #8E9DFF;
  --yellow:   #F1B01D;
  --text:     #1a2e26;
  --text-mid: #3d5a4e;
  --r-lg:     20px;
  --r-md:     14px;
  --r-sm:     10px;
}

.lg-sakums .pn-page {
  font-family: 'Source Serif 4', Georgia, serif;
  background: var(--cream);
  color: var(--text);
  font-size: 17px;
  line-height: 1.65;
  overflow-x: hidden;
  scroll-behavior: smooth;
}
.lg-sakums .pn-page a { color: inherit; text-decoration: none; }
.lg-sakums .pn-page img { display: block; max-width: 100%; height: auto; }

/* ═══════════════════════════════════════════
   TYPOGRAPHY
═══════════════════════════════════════════ */
.lg-sakums h1, .lg-sakums h2, .lg-sakums h3, .lg-sakums h4, .lg-sakums .hn-sans {
  font-family: 'Figtree', 'Helvetica Neue', Arial, sans-serif;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.lg-sakums .eyebrow {
  font-family: 'Figtree', sans-serif;
  font-weight: 600;
  font-size: 11px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--green);
  display: block;
  margin-bottom: 14px;
}

/* ═══════════════════════════════════════════
   LAYOUT
═══════════════════════════════════════════ */
.lg-sakums .pn-wrap {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 32px;
}
.lg-sakums .pn-section { padding: 88px 0; }
.lg-sakums .pn-section-sm { padding: 60px 0; }

/* ═══════════════════════════════════════════
   BUTTONS
═══════════════════════════════════════════ */
.lg-sakums .pn-btn {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: 'Figtree', sans-serif;
  font-weight: 700; font-size: 14px;
  padding: 12px 24px; border-radius: 100px;
  cursor: pointer; border: none;
  transition: transform .15s ease, box-shadow .15s ease, background .15s ease;
  white-space: nowrap; text-decoration: none;
}
.lg-sakums .pn-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,.12); }
.lg-sakums .pn-btn:active { transform: translateY(0); }
.lg-sakums .pn-btn-green  { background: var(--green); color: var(--cream); }
.lg-sakums .pn-btn-outline { background: transparent; color: var(--green); border: 2px solid var(--green); }
.lg-sakums .pn-btn-cream  { background: var(--cream); color: var(--green); }
.lg-sakums .pn-btn-orange { background: var(--orange); color: #fff; }
.lg-sakums .pn-btn-white-outline { background: transparent; color: #fff; border: 2px solid rgba(255,255,255,.5); }
.lg-sakums .pn-btn-sm { padding: 9px 18px; font-size: 13px; }

/* ═══════════════════════════════════════════
   BACKGROUND FIGURES
═══════════════════════════════════════════ */
.lg-sakums .pn-figures-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}
.lg-sakums .pn-fig {
  position: absolute;
  opacity: 0.13;
}

/* ═══════════════════════════════════════════
   1. HERO IMAGE
═══════════════════════════════════════════ */
.lg-sakums .pn-hero-img {
  width: 100%;
  display: block;
  position: relative;
  overflow: hidden;
  background: #1a2e26;
}
.lg-sakums .pn-hero-img::after {
  content: '';
  position: absolute;
  top: 0; right: 0; bottom: 0;
  width: 12px;
  background: var(--cream);
  z-index: 5;
}
.lg-sakums .pn-hero-img img {
  width: 100%;
  max-height: 92vh;
  object-fit: cover;
  object-position: center 30%;
  display: block;
}

/* ═══════════════════════════════════════════
   2. AKTUĀLI
═══════════════════════════════════════════ */
.lg-sakums .pn-aktuali {
  background: var(--cream);
  padding: 80px 0;
}
.lg-sakums .pn-aktuali-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 48px;
  gap: 20px;
}
.lg-sakums .pn-aktuali-header h2 {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  color: var(--green);
}
.lg-sakums .pn-aktuali-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

/* Carousel */
.lg-sakums .pn-carousel {
  position: relative;
}
.lg-sakums .pn-carousel-viewport {
  overflow: hidden;
}
.lg-sakums .pn-carousel-track {
  display: flex;
  gap: 28px;
  will-change: transform;
  transition: transform .5s cubic-bezier(.4,0,.2,1);
}
.lg-sakums .pn-carousel-track .pn-card {
  flex: 0 0 calc((100% - 56px) / 3);
  min-width: calc((100% - 56px) / 3);
}
.lg-sakums .pn-carousel-nav {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 36px;
}
.lg-sakums .pn-carousel-btn {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 2px solid var(--green);
  background: transparent;
  color: var(--green);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background .15s, color .15s, transform .15s;
}
.lg-sakums .pn-carousel-btn:hover { background: var(--green); color: var(--cream); transform: translateY(-2px); }
.lg-sakums .pn-carousel-btn svg { width: 18px; height: 18px; }
.lg-sakums .pn-carousel-dots {
  display: flex; align-items: center; gap: 7px;
  margin: 0 8px;
}
.lg-sakums .pn-carousel-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: rgba(42,94,74,.2);
  transition: background .2s, transform .2s;
  cursor: pointer;
}
.lg-sakums .pn-carousel-dot.active { background: var(--green); transform: scale(1.3); }
.lg-sakums .pn-card {
  background: #fff;
  border-radius: var(--r-lg);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease;
  border: 1px solid rgba(42,94,74,.07);
}
.lg-sakums .pn-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(42,94,74,.12);
}
.lg-sakums .pn-card-img {
  aspect-ratio: 1/1;
  overflow: hidden;
  background: var(--green);
}
.lg-sakums .pn-card-img img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.lg-sakums .pn-card:hover .pn-card-img img { transform: scale(1.04); }
.lg-sakums .pn-card-img-placeholder {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
}
.lg-sakums .pn-card-body {
  padding: 24px 26px 26px;
  display: flex; flex-direction: column;
  flex: 1;
  gap: 12px;
}
.lg-sakums .pn-card-tag {
  font-family: 'Figtree', sans-serif;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--orange);
}
.lg-sakums .pn-card-title {
  font-family: 'Figtree', sans-serif;
  font-weight: 800;
  font-size: 1.05rem;
  line-height: 1.25;
  color: var(--green);
}
.lg-sakums .pn-card-desc {
  font-size: 0.9rem;
  color: var(--text-mid);
  line-height: 1.6;
  flex: 1;
}
.lg-sakums .pn-card-footer { margin-top: auto; padding-top: 8px; }

/* ═══════════════════════════════════════════
   3. KAS IR PATNIS
═══════════════════════════════════════════ */
.lg-sakums .pn-about {
  background: var(--green);
  padding: 96px 0;
  position: relative;
  overflow: hidden;
}
.lg-sakums .pn-about-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.lg-sakums .pn-about-text h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
  color: var(--cream);
  margin-bottom: 28px;
}
.lg-sakums .pn-about-text p {
  color: rgba(255,248,238,.75);
  font-size: 1rem;
  line-height: 1.75;
  margin-bottom: 18px;
}
.lg-sakums .pn-about-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.lg-sakums .pn-stat {
  background: rgba(255,248,238,.08);
  border: 1px solid rgba(255,248,238,.12);
  border-radius: var(--r-md);
  padding: 24px 20px;
}
.lg-sakums .pn-stat-num {
  font-family: 'Figtree', sans-serif;
  font-weight: 800;
  font-size: 2.4rem;
  color: var(--yellow);
  line-height: 1;
  margin-bottom: 6px;
}
.lg-sakums .pn-stat-label {
  font-size: 0.85rem;
  color: rgba(255,248,238,.65);
  line-height: 1.4;
}

/* About figures */
.lg-sakums .pn-about .pn-fig { opacity: 0.08; }

/* ═══════════════════════════════════════════
   4. VIRZIENI
═══════════════════════════════════════════ */
.lg-sakums .pn-virzieni {
  background: var(--cream);
  padding: 88px 0;
}
.lg-sakums .pn-virzieni-header {
  text-align: center;
  margin-bottom: 56px;
}
.lg-sakums .pn-virzieni-header h2 {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  color: var(--green);
}
.lg-sakums .pn-virzieni-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.lg-sakums .pn-virz-card {
  background: #fff;
  border-radius: var(--r-lg);
  padding: 36px 28px 32px;
  display: flex; flex-direction: column;
  gap: 16px;
  border: 1px solid rgba(42,94,74,.08);
  transition: transform .2s ease, box-shadow .2s ease;
  position: relative;
  overflow: hidden;
}
.lg-sakums .pn-virz-card::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0;
  height: 4px;
}
.lg-sakums .pn-virz-card.c-orange::before { background: var(--orange); }
.lg-sakums .pn-virz-card.c-blue::before   { background: var(--blue); }
.lg-sakums .pn-virz-card.c-yellow::before { background: var(--yellow); }
.lg-sakums .pn-virz-card.c-green::before  { background: var(--green); }
.lg-sakums .pn-virz-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 36px rgba(42,94,74,.1);
}
.lg-sakums .pn-virz-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 22px;
}
.lg-sakums .pn-virz-card.c-orange .pn-virz-icon { background: rgba(255,144,104,.12); }
.lg-sakums .pn-virz-card.c-blue   .pn-virz-icon { background: rgba(142,157,255,.12); }
.lg-sakums .pn-virz-card.c-yellow .pn-virz-icon { background: rgba(241,176,29,.12); }
.lg-sakums .pn-virz-card.c-green  .pn-virz-icon { background: rgba(42,94,74,.08); }
.lg-sakums .pn-virz-age {
  font-family: 'Figtree', sans-serif;
  font-weight: 700;
  font-size: 11px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--text-mid);
  opacity: .7;
}
.lg-sakums .pn-virz-title {
  font-family: 'Figtree', sans-serif;
  font-weight: 800;
  font-size: 1.15rem;
  color: var(--green);
  line-height: 1.2;
}
.lg-sakums .pn-virz-desc {
  font-size: 0.88rem;
  color: var(--text-mid);
  line-height: 1.6;
  flex: 1;
}
.lg-sakums .pn-virz-link {
  font-family: 'Figtree', sans-serif;
  font-weight: 700;
  font-size: 13px;
  color: var(--green);
  display: inline-flex; align-items: center; gap: 5px;
  transition: gap .15s;
}
.lg-sakums .pn-virz-card:hover .pn-virz-link { gap: 10px; }
.lg-sakums .pn-virz-link::after { content: '→'; }

/* ═══════════════════════════════════════════
   5. STEAM
═══════════════════════════════════════════ */
.lg-sakums .pn-steam {
  background: #f0ebe0;
  padding: 88px 0;
  position: relative;
  overflow: hidden;
}
.lg-sakums .pn-steam-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
  position: relative; z-index: 1;
}
.lg-sakums .pn-steam-text .eyebrow { color: var(--orange); }
.lg-sakums .pn-steam-text h2 {
  font-size: clamp(1.7rem, 2.8vw, 2.4rem);
  color: var(--green);
  margin-bottom: 22px;
}
.lg-sakums .pn-steam-text p {
  color: var(--text-mid);
  font-size: 1rem;
  line-height: 1.75;
  margin-bottom: 32px;
}
.lg-sakums .pn-steam-points {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.lg-sakums .pn-steam-pt {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: 0.9rem; color: var(--text); line-height: 1.5;
}
.lg-sakums .pn-steam-pt::before {
  content: '';
  flex-shrink: 0;
  width: 8px; height: 8px;
  background: var(--orange);
  border-radius: 50%;
  margin-top: 6px;
}
.lg-sakums .pn-steam-visual {
  position: relative;
  display: flex; align-items: center; justify-content: center;
}
.lg-sakums .pn-steam-badge {
  background: var(--green);
  color: var(--cream);
  border-radius: var(--r-lg);
  padding: 40px 36px;
  text-align: center;
  max-width: 340px;
}
.lg-sakums .pn-steam-badge-word {
  font-family: 'Figtree', sans-serif;
  font-weight: 800;
  font-size: 1.5rem;
  letter-spacing: .06em;
  color: var(--yellow);
  display: block;
  margin-bottom: 10px;
}
.lg-sakums .pn-steam-badge p {
  font-size: 0.88rem;
  color: rgba(255,248,238,.7);
  line-height: 1.55;
}
.lg-sakums .pn-steam-tag-row {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-top: 20px;
}
.lg-sakums .pn-steam-tag {
  font-family: 'Figtree', sans-serif;
  font-weight: 600; font-size: 12px;
  background: rgba(255,248,238,.1);
  color: var(--cream);
  border-radius: 100px;
  padding: 5px 14px;
  border: 1px solid rgba(255,248,238,.15);
}

/* ═══════════════════════════════════════════
   6. KĀPĒC PATNIS
═══════════════════════════════════════════ */
.lg-sakums .pn-kapec {
  background: var(--cream);
  padding: 88px 0;
}
.lg-sakums .pn-kapec-header {
  text-align: center;
  margin-bottom: 56px;
}
.lg-sakums .pn-kapec-header h2 {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  color: var(--green);
}
.lg-sakums .pn-kapec-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.lg-sakums .pn-kapec-item {
  background: #fff;
  border-radius: var(--r-md);
  padding: 28px 22px;
  display: flex; flex-direction: column; gap: 14px;
  border: 1px solid rgba(42,94,74,.07);
  transition: transform .2s, box-shadow .2s;
}
.lg-sakums .pn-kapec-item:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(42,94,74,.1);
}
.lg-sakums .pn-kapec-emoji {
  font-size: 28px;
  line-height: 1;
}
.lg-sakums .pn-kapec-title {
  font-family: 'Figtree', sans-serif;
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--green);
  line-height: 1.3;
}

/* ═══════════════════════════════════════════
   7. CEĻVEDIS CTA
═══════════════════════════════════════════ */
.lg-sakums .pn-celvedis {
  background: var(--orange);
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.lg-sakums .pn-celvedis-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 48px;
  align-items: center;
  position: relative; z-index: 1;
}
.lg-sakums .pn-celvedis-text h2 {
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  color: #fff;
  margin-bottom: 16px;
}
.lg-sakums .pn-celvedis-text p {
  color: rgba(255,255,255,.85);
  font-size: 1rem;
  line-height: 1.7;
  max-width: 540px;
}
.lg-sakums .pn-celvedis-cta { display: flex; align-items: center; }

/* Orange section figures */
.lg-sakums .pn-celvedis .pn-fig { opacity: 0.1; }

/* ═══════════════════════════════════════════
   9. MEDIJI
═══════════════════════════════════════════ */
.lg-sakums .pn-mediji {
  background: var(--cream);
  padding: 88px 0;
}
.lg-sakums .pn-mediji-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.lg-sakums .pn-mediji-text h2 {
  font-size: clamp(1.7rem, 2.8vw, 2.4rem);
  color: var(--green);
  margin-bottom: 20px;
}
.lg-sakums .pn-mediji-text p {
  color: var(--text-mid);
  line-height: 1.75;
  margin-bottom: 32px;
}
.lg-sakums .pn-mediji-logos {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.lg-sakums .pn-media-logo {
  background: #fff;
  border-radius: var(--r-md);
  padding: 20px 18px;
  display: flex; align-items: center; justify-content: center;
  border: 1px solid rgba(42,94,74,.07);
  min-height: 72px;
  font-family: 'Figtree', sans-serif;
  font-weight: 800;
  font-size: 0.95rem;
  color: var(--text-mid);
  opacity: .7;
  text-align: center;
}

/* ═══════════════════════════════════════════
   10. FINAL CTA
═══════════════════════════════════════════ */
.lg-sakums .pn-final-cta {
  background: var(--green);
  padding: 96px 0;
  position: relative;
  overflow: hidden;
}
.lg-sakums .pn-final-cta-inner {
  text-align: center;
  position: relative; z-index: 1;
  max-width: 620px;
  margin: 0 auto;
}
.lg-sakums .pn-final-cta h2 {
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  color: var(--cream);
  margin-bottom: 20px;
}
.lg-sakums .pn-final-cta p {
  color: rgba(255,248,238,.75);
  font-size: 1.05rem;
  line-height: 1.7;
  margin-bottom: 40px;
}
.lg-sakums .pn-final-cta-btns {
  display: flex; gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
.lg-sakums .pn-final-cta .pn-fig { opacity: 0.07; }

/* ═══════════════════════════════════════════
   RESPONSIVE
═══════════════════════════════════════════ */
@media (max-width: 1024px) {
  .lg-sakums .pn-virzieni-grid { grid-template-columns: repeat(2, 1fr); }
  .lg-sakums .pn-kapec-grid { grid-template-columns: repeat(2, 1fr); }
  .lg-sakums .pn-about-inner { grid-template-columns: 1fr; gap: 48px; }
  .lg-sakums .pn-steam-inner { grid-template-columns: 1fr; gap: 48px; }
  .lg-sakums .pn-mediji-inner { grid-template-columns: 1fr; gap: 48px; }
  .lg-sakums .pn-celvedis-inner { grid-template-columns: 1fr; gap: 32px; }
  .lg-sakums .pn-carousel-track .pn-card { flex: 0 0 calc((100% - 28px) / 2); min-width: calc((100% - 28px) / 2); }
}
@media (max-width: 768px) {
  .lg-sakums .pn-wrap { padding: 0 20px; }
  .lg-sakums .pn-section { padding: 60px 0; }
  .lg-sakums .pn-news-grid { grid-template-columns: repeat(2, 1fr); }
  .lg-sakums .pn-virzieni-grid { grid-template-columns: 1fr 1fr; }
  .lg-sakums .pn-steam-points { grid-template-columns: 1fr; }
  .lg-sakums .pn-about-stats { grid-template-columns: 1fr 1fr; }
  .lg-sakums .pn-carousel-track .pn-card { flex: 0 0 100%; min-width: 100%; }
}
@media (max-width: 540px) {
  .lg-sakums .pn-kapec-grid { grid-template-columns: 1fr 1fr; }
  .lg-sakums .pn-news-grid { grid-template-columns: 1fr; }
  .lg-sakums .pn-virzieni-grid { grid-template-columns: 1fr; }
  .lg-sakums .pn-mediji-logos { grid-template-columns: repeat(2, 1fr); }
  .lg-sakums .pn-aktuali-header { flex-direction: column; align-items: flex-start; }
}

sections.js:
(function () {
  var track = document.getElementById('pn-aktuali-track');
  var viewport = track ? track.parentElement : null;
  var prevBtn = document.getElementById('pn-aktuali-prev');
  var nextBtn = document.getElementById('pn-aktuali-next');
  var dotsWrap = document.getElementById('pn-aktuali-dots');
  if (!track || !viewport) return;

  var cards = Array.prototype.slice.call(track.children);
  var total = cards.length;
  var visible = 3; // desktop default, recalculated below
  var index = 0;
  var autoTimer = null;
  var AUTO_MS = 5000;

  function getVisibleCount() {
    var w = window.innerWidth;
    if (w <= 768) return 1;
    if (w <= 1024) return 2;
    return 3;
  }

  function maxIndex() {
    return Math.max(0, total - visible);
  }

  function goTo(i) {
    visible = getVisibleCount();
    index = Math.max(0, Math.min(i, maxIndex()));
    var card = cards[0];
    var gap = 28;
    var cardWidth = card.getBoundingClientRect().width;
    var offset = index * (cardWidth + gap);
    track.style.transform = 'translateX(-' + offset + 'px)';
    updateDots();
  }

  function next() {
    visible = getVisibleCount();
    if (index >= maxIndex()) { goTo(0); } else { goTo(index + 1); }
  }

  function prev() {
    visible = getVisibleCount();
    if (index <= 0) { goTo(maxIndex()); } else { goTo(index - 1); }
  }

  function buildDots() {
    dotsWrap.innerHTML = '';
    visible = getVisibleCount();
    var dotCount = maxIndex() + 1;
    for (var i = 0; i < dotCount; i++) {
      var dot = document.createElement('span');
      dot.className = 'pn-carousel-dot' + (i === index ? ' active' : '');
      dot.addEventListener('click', function (idx) {
        return function () { stopAuto(); goTo(idx); startAuto(); };
      }(i));
      dotsWrap.appendChild(dot);
    }
  }

  function updateDots() {
    var dots = dotsWrap.children;
    for (var i = 0; i < dots.length; i++) {
      dots[i].className = 'pn-carousel-dot' + (i === index ? ' active' : '');
    }
  }

  function startAuto() {
    stopAuto();
    autoTimer = setInterval(next, AUTO_MS);
  }
  function stopAuto() {
    if (autoTimer) { clearInterval(autoTimer); autoTimer = null; }
  }

  nextBtn.addEventListener('click', function () { stopAuto(); next(); startAuto(); });
  prevBtn.addEventListener('click', function () { stopAuto(); prev(); startAuto(); });
  viewport.addEventListener('mouseenter', stopAuto);
  viewport.addEventListener('mouseleave', startAuto);

  var resizeTimer = null;
  window.addEventListener('resize', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      buildDots();
      goTo(index);
    }, 150);
  });

  buildDots();
  goTo(0);
  startAuto();
})();

sections.css:
.lg-pirmsskola {
  --green:  #2A5E4A;
  --cream:  #FFF8EE;
  --orange: #FF9068;
  --blue:   #8E9DFF;
  --yellow: #F1B01D;
  --r:      16px;
  --r-lg:   24px;
  --serif:  'Source Serif 4', Georgia, serif;
  --sans:   'Helvetica Neue', Arial, sans-serif;
}
.lg-pirmsskola * { margin: 0; padding: 0; box-sizing: border-box; }
.lg-pirmsskola { scroll-behavior: smooth; }
.lg-pirmsskola {
  background: var(--cream);
  color: var(--green);
  font-family: var(--serif);
  overflow-x: hidden;
}
/* ── BG FIGURES ── */
.lg-pirmsskola .bg-layer {
  position: fixed;
  inset: 0;
  top: 80px;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}
.lg-pirmsskola .bg-fig {
  position: absolute;
  opacity: 0.10;
}
.lg-pirmsskola .bg-fig svg { display: block; width: 100%; height: 100%; }
@keyframes fa { 0%,100%{transform:translateY(0) rotate(0deg)} 50%{transform:translateY(-18px) rotate(4deg)} }
@keyframes fb { 0%,100%{transform:translateY(0) rotate(0deg)} 50%{transform:translateY(15px) rotate(-5deg)} }
@keyframes fc { 0%,100%{transform:translateY(0)} 40%{transform:translateY(-12px) rotate(3deg)} 70%{transform:translateY(8px) rotate(-2deg)} }
.lg-pirmsskola .bg-fig--35 { width: 80px;  top: 4%;    right: 3%;   animation: fa 13s ease-in-out infinite; }
.lg-pirmsskola .bg-fig--26 { width: 160px; bottom: 5%; left: 1.5%;  animation: fb 15s ease-in-out infinite 1s; }
.lg-pirmsskola .bg-fig--32 { width: 90px;  top: 44%;   right: 2.5%; animation: fc 12s ease-in-out infinite 2s; }
.lg-pirmsskola .bg-fig--31 { width: 85px;  top: 28%;   left: 1.5%;  animation: fa 14s ease-in-out infinite 0.5s; }
/* ── WRAPPER ── */
.lg-pirmsskola .wrap {
  position: relative;
  z-index: 1;
  max-width: 1160px;
  margin: 0 auto;
  padding: 48px 32px 80px;
}
/* ── TOP CTA BAR ── */
.lg-pirmsskola .top-cta-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--orange);
  border-radius: 100px;
  padding: 14px;
  margin-bottom: 20px;
}
.lg-pirmsskola .btn-cta-top {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--orange);
  font-family: var(--sans);
  font-weight: 700;
  font-size: 13px;
  padding: 12px 24px;
  border-radius: 100px;
  text-decoration: none;
  letter-spacing: 0.01em;
  transition: transform 0.2s, box-shadow 0.2s;
  white-space: nowrap;
}
.lg-pirmsskola .btn-cta-top:hover { transform: scale(1.04); box-shadow: 0 8px 24px rgba(0,0,0,0.14); }
/* ── HERO — split layout ── */
.lg-pirmsskola .hero {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 20px;
  margin-bottom: 24px;
  align-items: stretch;
}
.lg-pirmsskola .hero-main {
  background: var(--green);
  border-radius: var(--r-lg);
  padding: 56px 60px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 300px;
}
.lg-pirmsskola .hero-main::before {
  content: '';
  position: absolute;
  width: 420px; height: 420px;
  background: rgba(255,255,255,0.03);
  border-radius: 50%;
  top: -160px; right: -100px;
}
.lg-pirmsskola .hero-main blockquote {
  font-family: var(--sans);
  font-weight: 600;
  font-size: clamp(20px, 2.4vw, 30px);
  color: var(--cream);
  line-height: 1.25;
  letter-spacing: -0.02em;
  position: relative;
  z-index: 1;
  max-width: 580px;
}
.lg-pirmsskola .hero-accent {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 28px;
  position: relative;
  z-index: 1;
  flex-wrap: wrap;
}
.lg-pirmsskola .hero-pill {
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--green);
  background: var(--yellow);
  padding: 6px 16px;
  border-radius: 100px;
}
.lg-pirmsskola .hero-year {
  font-family: var(--serif);
  font-size: 13px;
  color: rgba(255,248,238,0.5);
}
.lg-pirmsskola .hero-aside {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.lg-pirmsskola .hero-stat {
  background: var(--orange);
  border-radius: var(--r-lg);
  padding: 32px 30px;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.lg-pirmsskola .hero-stat .num {
  font-family: var(--sans);
  font-weight: 800;
  font-size: 56px;
  color: #fff;
  line-height: 1;
  letter-spacing: -0.04em;
  margin-bottom: 6px;
}
.lg-pirmsskola .hero-stat .lbl {
  font-family: var(--serif);
  font-size: 14px;
  color: rgba(255,255,255,0.8);
  line-height: 1.4;
}
/* ── SECTION LABELS ── */
.lg-pirmsskola .s-label {
  font-family: var(--serif);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--orange);
  margin-bottom: 10px;
}
.lg-pirmsskola .s-title {
  font-family: var(--sans);
  font-weight: 700;
  font-size: clamp(24px, 3vw, 38px);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
}
.lg-pirmsskola .s-sub {
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1.65;
  color: rgba(42,94,74,0.65);
  max-width: 500px;
}
/* ── FILIĀLES ── */
.lg-pirmsskola .filiales-section { margin-bottom: 24px; }
.lg-pirmsskola .filiales-header { margin-bottom: 28px; }
.lg-pirmsskola .filiales-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
}
.lg-pirmsskola .fil-card {
  background: #fff;
  border-radius: var(--r-lg);
  padding: 26px 20px 22px;
  text-decoration: none;
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
  overflow: hidden;
  border: 1.5px solid rgba(42,94,74,0.08);
  transition: transform 0.22s, box-shadow 0.22s, border-color 0.22s;
  min-height: 170px;
}
.lg-pirmsskola .fil-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 14px 40px rgba(42,94,74,0.12);
  border-color: var(--orange);
}
.lg-pirmsskola .fil-card::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 3px;
  background: var(--orange);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.28s;
}
.lg-pirmsskola .fil-card:hover::before { transform: scaleX(1); }
.lg-pirmsskola .fil-img {
  width: 100%;
  height: 84px;
  border-radius: 12px;
  object-fit: cover;
  margin-bottom: 16px;
  display: block;
}
.lg-pirmsskola .fil-name {
  font-family: var(--sans);
  font-weight: 700;
  font-size: 14px;
  color: var(--green);
  line-height: 1.25;
  margin-bottom: 8px;
}
.lg-pirmsskola .fil-tag {
  display: inline-block;
  font-family: var(--serif);
  font-size: 11px;
  color: rgba(42,94,74,0.5);
  background: rgba(42,94,74,0.06);
  padding: 3px 10px;
  border-radius: 100px;
  margin-bottom: auto;
}
.lg-pirmsskola .fil-arrow {
  display: block;
  margin-top: 18px;
  font-size: 16px;
  color: var(--orange);
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity 0.2s, transform 0.2s;
}
.lg-pirmsskola .fil-card:hover .fil-arrow { opacity: 1; transform: translateX(0); }
/* ── CTA BANNER ── */
.lg-pirmsskola .cta-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 24px;
}
.lg-pirmsskola .cta-main {
  background: var(--orange);
  border-radius: var(--r-lg);
  padding: 44px 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 28px;
  position: relative;
  overflow: hidden;
}
.lg-pirmsskola .cta-main::after {
  content: '';
  position: absolute;
  width: 300px; height: 300px;
  background: rgba(255,255,255,0.06);
  border-radius: 50%;
  right: -80px; bottom: -80px;
}
.lg-pirmsskola .cta-main h2 {
  font-family: var(--sans);
  font-weight: 700;
  font-size: clamp(20px, 2.2vw, 28px);
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.15;
  position: relative; z-index: 1;
}
.lg-pirmsskola .cta-main p {
  font-family: var(--serif);
  font-size: 15px;
  color: rgba(255,255,255,0.82);
  line-height: 1.55;
  position: relative; z-index: 1;
}
.lg-pirmsskola .btn-white {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--orange);
  font-family: var(--sans);
  font-weight: 700;
  font-size: 13px;
  padding: 14px 28px;
  border-radius: 100px;
  text-decoration: none;
  letter-spacing: 0.01em;
  transition: transform 0.2s, box-shadow 0.2s;
  align-self: flex-start;
  position: relative; z-index: 1;
}
.lg-pirmsskola .btn-white:hover { transform: scale(1.04); box-shadow: 0 8px 24px rgba(0,0,0,0.14); }
.lg-pirmsskola .cta-secondary {
  background: var(--green);
  border-radius: var(--r-lg);
  padding: 44px 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 28px;
  position: relative;
  overflow: hidden;
}
.lg-pirmsskola .cta-secondary::after {
  content: '📖';
  position: absolute;
  right: -10px; bottom: -20px;
  font-size: 120px;
  opacity: 0.07;
  pointer-events: none;
}
.lg-pirmsskola .cta-secondary h3 {
  font-family: var(--sans);
  font-weight: 700;
  font-size: clamp(17px, 1.8vw, 22px);
  color: var(--cream);
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.lg-pirmsskola .cta-secondary p {
  font-family: var(--serif);
  font-size: 14px;
  color: rgba(255,248,238,0.65);
  line-height: 1.6;
}
.lg-pirmsskola .btn-yellow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--yellow);
  color: var(--green);
  font-family: var(--sans);
  font-weight: 700;
  font-size: 13px;
  padding: 13px 24px;
  border-radius: 100px;
  text-decoration: none;
  letter-spacing: 0.01em;
  transition: transform 0.2s, box-shadow 0.2s;
  align-self: flex-start;
}
.lg-pirmsskola .btn-yellow:hover { transform: scale(1.04); box-shadow: 0 8px 22px rgba(0,0,0,0.18); }
/* ── DIREKTORA SADAĻA ── */
.lg-pirmsskola .director-section { margin-bottom: 24px; }
.lg-pirmsskola .director-card {
  background: var(--green);
  border-radius: var(--r-lg);
  padding: 0;
  display: grid;
  grid-template-columns: 300px 1fr;
  align-items: stretch;
  position: relative;
  overflow: hidden;
}
.lg-pirmsskola .director-card::before {
  content: '';
  position: absolute;
  width: 380px; height: 380px;
  background: rgba(255,255,255,0.03);
  border-radius: 50%;
  top: -140px; right: -100px;
  pointer-events: none;
}
.lg-pirmsskola .director-photo {
  position: relative;
  background: var(--orange);
  min-height: 320px;
  overflow: hidden;
}
.lg-pirmsskola .director-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.lg-pirmsskola .director-content {
  padding: 48px 56px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 22px;
  position: relative;
  z-index: 1;
}
.lg-pirmsskola .director-quote-mark {
  font-family: var(--sans);
  font-weight: 800;
  font-size: 64px;
  color: var(--yellow);
  line-height: 0.6;
  opacity: 0.9;
}
.lg-pirmsskola .director-quote {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(17px, 1.7vw, 21px);
  line-height: 1.55;
  color: var(--cream);
  max-width: 560px;
}
.lg-pirmsskola .director-attribution {
  font-family: var(--serif);
  font-size: 13px;
  color: rgba(255,248,238,0.55);
}
.lg-pirmsskola .director-meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: 4px;
}
.lg-pirmsskola .director-name {
  font-family: var(--sans);
  font-weight: 700;
  font-size: 16px;
  color: var(--cream);
  letter-spacing: -0.01em;
}
.lg-pirmsskola .director-role {
  font-family: var(--serif);
  font-size: 13px;
  color: var(--yellow);
  letter-spacing: 0.02em;
}
/* ── JAUNUMI ── */
.lg-pirmsskola .jaunumi-section { margin-bottom: 24px; }
.lg-pirmsskola .jaunumi-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 12px;
}
.lg-pirmsskola .see-all {
  font-family: var(--serif);
  font-size: 13px;
  color: var(--orange);
  text-decoration: none;
  font-style: italic;
  transition: opacity 0.2s;
}
.lg-pirmsskola .see-all:hover { opacity: 0.7; }
/* Horizontal scroll track */
.lg-pirmsskola .n-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  cursor: grab;
  padding-bottom: 6px;
}
.lg-pirmsskola .n-track:active { cursor: grabbing; }
.lg-pirmsskola .n-track::-webkit-scrollbar { display: none; }
.lg-pirmsskola .n-card {
  scroll-snap-align: start;
  flex-shrink: 0;
  width: 260px;
  background: #fff;
  border-radius: var(--r-lg);
  overflow: hidden;
  text-decoration: none;
  display: block;
  border: 1.5px solid rgba(42,94,74,0.07);
  transition: transform 0.22s, box-shadow 0.22s;
  position: relative;
}
.lg-pirmsskola .n-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 14px 40px rgba(42,94,74,0.12);
}
.lg-pirmsskola .n-thumb {
  width: 100%; aspect-ratio: 1 / 1;
  display: flex; align-items: center; justify-content: center;
  font-size: 36px;
  position: relative;
  overflow: hidden;
}
.lg-pirmsskola .n-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.lg-pirmsskola .n-badge {
  position: absolute;
  top: 10px; left: 10px;
  background: var(--orange);
  color: #fff;
  font-family: var(--sans);
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 100px;
}
.lg-pirmsskola .n-body { padding: 16px 18px 20px; }
.lg-pirmsskola .n-date {
  font-family: var(--serif);
  font-size: 11px;
  color: rgba(42,94,74,0.4);
  margin-bottom: 5px;
}
.lg-pirmsskola .n-title {
  font-family: var(--sans);
  font-weight: 600;
  font-size: 14px;
  color: var(--green);
  line-height: 1.35;
  margin-bottom: 10px;
}
.lg-pirmsskola .n-more {
  font-family: var(--serif);
  font-size: 12px;
  color: var(--orange);
  font-style: italic;
}
.lg-pirmsskola .n-card-link {
  color: inherit;
  text-decoration: none;
}
.lg-pirmsskola .n-card-link::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
}
.lg-pirmsskola .carousel-nav {
  display: flex;
  gap: 10px;
  margin-top: 18px;
  justify-content: flex-end;
}
.lg-pirmsskola .c-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  border: 1.5px solid var(--green);
  background: transparent;
  color: var(--green);
  font-size: 16px;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.2s, color 0.2s;
}
.lg-pirmsskola .c-btn:hover { background: var(--green); color: var(--cream); }
/* ── SOCIAL ── */
.lg-pirmsskola .social-section { margin-bottom: 24px; }
.lg-pirmsskola .social-card {
  background: var(--green);
  border-radius: var(--r-lg);
  padding: 32px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 20px;
}
.lg-pirmsskola .social-text {
  font-family: var(--sans);
  font-weight: 700;
  font-size: 16px;
  color: var(--cream);
  letter-spacing: -0.01em;
  max-width: 460px;
  line-height: 1.4;
}
.lg-pirmsskola .social-links {
  display: flex;
  gap: 12px;
}
.lg-pirmsskola .social-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--cream);
  color: var(--green);
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  transition: transform 0.2s, background 0.2s, color 0.2s;
}
.lg-pirmsskola .social-btn:hover {
  background: var(--orange);
  color: #fff;
  transform: scale(1.08);
}
/* ── VIDEO ── */
.lg-pirmsskola .video-section { margin-bottom: 24px; }
.lg-pirmsskola .video-header { margin-bottom: 20px; }
.lg-pirmsskola .video-card {
  position: relative;
  border-radius: var(--r-lg);
  overflow: hidden;
  cursor: pointer;
  aspect-ratio: 21 / 9;
  background: var(--green);
  border: none;
  display: block;
  width: 100%;
  padding: 0;
}
.lg-pirmsskola .video-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  opacity: 0.85;
