  max-width: 70%;
  line-height: 1.3;
}
.lg-pirmsskola .video-lightbox {
  position: fixed;
  inset: 0;
  background: rgba(20,40,32,0.92);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 999;
  padding: 24px;
}
.lg-pirmsskola .video-lightbox.open { display: flex; }
.lg-pirmsskola .video-lightbox-inner {
  position: relative;
  width: 100%;
  max-width: 960px;
  aspect-ratio: 16 / 9;
  background: #000;
  border-radius: 16px;
  overflow: hidden;
}
.lg-pirmsskola .video-lightbox-inner iframe,
.lg-pirmsskola .video-lightbox-inner video {
  width: 100%;
  height: 100%;
  display: block;
  border: 0;
}
.lg-pirmsskola .video-close {
  position: absolute;
  top: -44px; right: 0;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--cream);
  color: var(--green);
  border: none;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
/* ── FADE-UP ── */
.lg-pirmsskola .fu { opacity: 0; transform: translateY(24px); transition: opacity 0.55s, transform 0.55s; }
.lg-pirmsskola .fu.vis { opacity: 1; transform: translateY(0); }
.lg-pirmsskola .fu:nth-child(2) { transition-delay: 0.08s; }
.lg-pirmsskola .fu:nth-child(3) { transition-delay: 0.16s; }
/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .lg-pirmsskola .filiales-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 900px) {
  .lg-pirmsskola .hero { grid-template-columns: 1fr; }
  .lg-pirmsskola .hero-aside { flex-direction: row; }
  .lg-pirmsskola .cta-row { grid-template-columns: 1fr; }
  .lg-pirmsskola .director-card { grid-template-columns: 1fr; }
  .lg-pirmsskola .director-photo { min-height: 220px; }
  .lg-pirmsskola .director-content { padding: 36px 32px; }
}
@media (max-width: 680px) {
  .lg-pirmsskola .wrap { padding: 28px 18px 60px; }
  .lg-pirmsskola .hero-main { padding: 36px 30px; }
  .lg-pirmsskola .hero-aside { flex-direction: column; }
  .lg-pirmsskola .filiales-grid { grid-template-columns: repeat(2, 1fr); }
  .lg-pirmsskola .cta-main, .lg-pirmsskola .cta-secondary { padding: 32px 28px; }
  .lg-pirmsskola .top-cta-bar { padding: 12px; }
  .lg-pirmsskola .top-cta-text { font-size: 13px; }
  .lg-pirmsskola .social-card { padding: 28px 30px; justify-content: center; text-align: center; }
  .lg-pirmsskola .video-card { aspect-ratio: 4 / 3; }
  .lg-pirmsskola .video-play { width: 60px; height: 60px; }
  .lg-pirmsskola .video-title-overlay { left: 20px; bottom: 18px; max-width: 85%; }
}
@media (max-width: 420px) {
  .lg-pirmsskola .filiales-grid { grid-template-columns: 1fr; }
}

