const obs = new IntersectionObserver(entries => {
  entries.forEach(e => {
    if (e.isIntersecting) { e.target.classList.add('vis'); obs.unobserve(e.target); }
  });
}, { threshold: 0.08 });
document.querySelectorAll('.fu').forEach(el => obs.observe(el));
const track = document.getElementById('nTrack');
const STEP = 276;
document.getElementById('nNext').addEventListener('click', () => track.scrollBy({ left: STEP, behavior: 'smooth' }));
document.getElementById('nPrev').addEventListener('click', () => track.scrollBy({ left: -STEP, behavior: 'smooth' }));
let down = false, sx, sl;
track.addEventListener('mousedown', e => { down = true; sx = e.pageX - track.offsetLeft; sl = track.scrollLeft; });
['mouseleave','mouseup'].forEach(ev => track.addEventListener(ev, () => down = false));
track.addEventListener('mousemove', e => {
  if (!down) return; e.preventDefault();
  track.scrollLeft = sl - (e.pageX - track.offsetLeft - sx) * 1.4;
});

sections.css:
.lg-makslu-skola {
  --green: #2A5E4A;
  --cream: #FFF8EE;
  --gold:  #F1B01D;
}

.lg-makslu-skola * { margin: 0; padding: 0; box-sizing: border-box; }

.lg-makslu-skola {
  background: var(--cream);
  color: var(--green);
  font-family: 'Source Serif 4', Georgia, serif;
  min-height: 100vh;
  overflow-x: hidden;
}

.lg-makslu-skola .figures-bg {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.lg-makslu-skola .fig { position: absolute; opacity: 0.13; }

.lg-makslu-skola .fig-2 {
  width: 420px; top: -60px; left: -80px;
  transform: rotate(-18deg);
  animation: float1 18s ease-in-out infinite;
}
.lg-makslu-skola .fig-5 {
  width: 340px; bottom: 40px; right: -60px;
  transform: rotate(12deg);
  animation: float2 22s ease-in-out infinite;
}
.lg-makslu-skola .fig-6 {
  width: 300px; top: 45%; left: -40px;
  transform: rotate(5deg);
  animation: float3 26s ease-in-out infinite;
}

@keyframes float1 { 0%,100%{transform:rotate(-18deg) translateY(0)} 50%{transform:rotate(-14deg) translateY(18px)} }
@keyframes float2 { 0%,100%{transform:rotate(12deg) translateY(0)} 50%{transform:rotate(8deg) translateY(-22px)} }
@keyframes float3 { 0%,100%{transform:rotate(5deg) translateY(0)} 50%{transform:rotate(9deg) translateY(14px)} }

.lg-makslu-skola main {
  position: relative;
  z-index: 10;
  max-width: 860px;
  margin: 0 auto;
  padding: 5rem 3rem 6rem;
}

.lg-makslu-skola .kp-label {
  display: inline-block;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--green);
  background: var(--gold);
  padding: 0.3rem 0.75rem;
  border-radius: 2px;
  margin-bottom: 2rem;
}

.lg-makslu-skola .kp-title {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(2.6rem, 5vw, 4rem);
  line-height: 1.03;
  letter-spacing: -0.03em;
  color: var(--green);
  margin-bottom: 2rem;
}

.lg-makslu-skola .kp-intro {
  font-size: 1.12rem;
  line-height: 1.78;
  color: var(--green);
  max-width: 620px;
  margin-bottom: 1.1rem;
  opacity: 0.82;
}

.lg-makslu-skola .kp-intro strong { font-weight: 600; opacity: 1; color: var(--green); }

.lg-makslu-skola .divider {
  width: 48px; height: 3px;
  background: var(--gold);
  border-radius: 2px;
  margin: 3rem 0;
}

.lg-makslu-skola .choose-label {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(42,94,74,0.4);
  margin-bottom: 1.25rem;
}

/* ── DEPT CARDS ── */
.lg-makslu-skola .dept-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1rem;
  align-items: stretch;
}

.lg-makslu-skola .dept-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  text-decoration: none;
  border-radius: 6px;
  padding: 2.25rem 1.9rem;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.lg-makslu-skola .dept-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 40px rgba(42,94,74,0.18);
}

.lg-makslu-skola .dept-card.art   { background: var(--green); }
.lg-makslu-skola .dept-card.music { background: var(--gold); }
.lg-makslu-skola .dept-card.adazi {
  background: var(--cream);
  border: 2px solid var(--green);
}

.lg-makslu-skola .dept-card-tag {
  display: block;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}

.lg-makslu-skola .dept-card.art   .dept-card-tag { color: rgba(255,248,238,0.4); }
.lg-makslu-skola .dept-card.music .dept-card-tag { color: rgba(42,94,74,0.45); }
.lg-makslu-skola .dept-card.adazi .dept-card-tag { color: rgba(42,94,74,0.5); }

.lg-makslu-skola .dept-card-title {
  display: block;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  line-height: 1.06;
  letter-spacing: -0.025em;
  margin-bottom: 1rem;
}

.lg-makslu-skola .dept-card.art   .dept-card-title { color: var(--cream); }
.lg-makslu-skola .dept-card.music .dept-card-title { color: var(--green); }
.lg-makslu-skola .dept-card.adazi .dept-card-title { color: var(--green); }

.lg-makslu-skola .dept-card-desc {
  display: block;
  font-family: 'Source Serif 4', serif;
  font-size: 0.92rem;
  line-height: 1.65;
  margin-bottom: 0;
  flex: 1;
}

.lg-makslu-skola .dept-card.art   .dept-card-desc { color: rgba(255,248,238,0.62); }
.lg-makslu-skola .dept-card.music .dept-card-desc { color: rgba(42,94,74,0.68); }
.lg-makslu-skola .dept-card.adazi .dept-card-desc { color: rgba(42,94,74,0.7); }

.lg-makslu-skola .dept-card-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 1.5rem;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.lg-makslu-skola .dept-card.art   .dept-card-cta { color: var(--gold); }
.lg-makslu-skola .dept-card.music .dept-card-cta { color: var(--green); }
.lg-makslu-skola .dept-card.adazi .dept-card-cta { color: var(--gold); }

.lg-makslu-skola .dept-card-cta::after { content: '→'; transition: transform 0.2s; }
.lg-makslu-skola .dept-card:hover .dept-card-cta::after { transform: translateX(4px); }

/* ── DOCS DROPDOWN ── */
.lg-makslu-skola .docs-section { margin-top: 3rem; }

.lg-makslu-skola .docs-toggle {
  width: 100%;
  background: none;
  border: none;
  border-top: 1.5px solid var(--green);
  border-bottom: 1.5px solid var(--green);
  padding: 1.1rem 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  color: var(--green);
  transition: opacity 0.2s;
}
.lg-makslu-skola .docs-toggle:hover { opacity: 0.65; }

.lg-makslu-skola .docs-toggle-label {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.lg-makslu-skola .docs-arrow {
  font-size: 1rem;
  line-height: 1;
  transition: transform 0.3s ease;
  display: inline-block;
}
.lg-makslu-skola .docs-toggle[aria-expanded="true"] .docs-arrow { transform: rotate(180deg); }

.lg-makslu-skola .docs-body { overflow: hidden; max-height: 0; transition: max-height 0.45s ease; }
.lg-makslu-skola .docs-body.open { max-height: 1400px; }

.lg-makslu-skola .docs-inner { padding: 0.5rem 0 1rem; }

@media (max-width: 900px) {
  .lg-makslu-skola .dept-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
  .lg-makslu-skola main { padding: 3rem 1.5rem 4rem; }
  .lg-makslu-skola .dept-grid { grid-template-columns: 1fr; }
  .lg-makslu-skola .fig-2 { width: 260px; }
  .lg-makslu-skola .fig-5 { width: 220px; }
  .lg-makslu-skola .fig-6 { width: 200px; }
}

