  .lg-makslu-skola-interesu-izglitiba .prog-card-body { padding: 1.4rem 1.75rem; }

  /* ── Feature list ── */
  .lg-makslu-skola-interesu-izglitiba .feature-list { list-style: none; margin-bottom: 1.4rem; }
