  @media (max-width: 600px) {
    .lg-makslu-skola-interesu-izglitiba main { padding: 3rem 1.1rem 5rem; }
    .lg-makslu-skola-interesu-izglitiba .prog-card-header, .lg-makslu-skola-interesu-izglitiba .prog-card-body { padding-left: 1.25rem; padding-right: 1.25rem; }
    .lg-makslu-skola-interesu-izglitiba .fig-1 { width: 210px; }
    .lg-makslu-skola-interesu-izglitiba .fig-2 { width: 160px; }
    .lg-makslu-skola-interesu-izglitiba .fig-3, .lg-makslu-skola-interesu-izglitiba .fig-4 { display: none; }
  }

/* ── Brand tokens ── */
  .lg-kontakti {
    --green:   #2A5E4A;
    --cream:   #FFF8EE;
    --orange:  #FF9068;
    --blue:    #8E9DFF;
    --yellow:  #F1B01D;
    --text:    #1a3a2d;
    --muted:   #5a7a6a;
    --radius:  16px;
    --gap:     2rem;
  }

  /* ── Reset ── */
  .lg-kontakti *, .lg-kontakti *::before, .lg-kontakti *::after { box-sizing: border-box; margin: 0; padding: 0; }
  .lg-kontakti { scroll-behavior: smooth; }

  /* ── Body ── */
  .lg-kontakti {
    background: var(--cream);
    color: var(--text);
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 1rem;
    line-height: 1.6;
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* ── TT Norms substitute – system sans ── */
  .lg-kontakti .sans {
    font-family: 'TT Norms Pro', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-weight: 600;
    letter-spacing: -.02em;
  }

  /* ── Figures decoration ── */
  .lg-kontakti .figures-bg {
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    overflow: hidden;
  }
  .lg-kontakti .fig {
    position: absolute;
    opacity: .18;
  }
  .lg-kontakti .fig-1 { width: 320px; top: -40px; right: -60px; transform: rotate(12deg); }
  .lg-kontakti .fig-2 { width: 260px; bottom: 80px; left: -50px; transform: rotate(-18deg); }
  .lg-kontakti .fig-3 { width: 200px; top: 45%; right: 5%; transform: rotate(30deg); opacity: .15; }
  .lg-kontakti .fig-4 { width: 180px; bottom: 10%; right: 15%; transform: rotate(-8deg); opacity: .15; }

  /* ── Layout ── */
  .lg-kontakti main {
    position: relative;
    z-index: 1;
    max-width: 820px;
    margin: 0 auto;
    padding: 4rem 1.5rem 6rem;
  }

  /* ── Header ── */
  .lg-kontakti .page-header {
    margin-bottom: 3rem;
  }
  .lg-kontakti .page-header .label {
    display: inline-block;
    font-size: .7rem;
    letter-spacing: .18em;
    text-transform: uppercase;
    color: var(--green);
    font-family: 'TT Norms Pro', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-weight: 600;
    margin-bottom: .75rem;
  }
  .lg-kontakti .page-header h1 {
    font-family: 'TT Norms Pro', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-weight: 700;
    font-size: clamp(2.4rem, 6vw, 3.8rem);
    line-height: 1.05;
    color: var(--green);
    letter-spacing: -.03em;
  }
  .lg-kontakti .page-header .tagline {
    margin-top: .75rem;
    font-size: 1.05rem;
    color: var(--muted);
    font-style: italic;
    line-height: 1.35;
  }

  /* ── Quick-contacts strip ── */
  .lg-kontakti .quick-contacts {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 3rem;
  }
  .lg-kontakti .qc-pill {
    display: inline-flex;
    align-items: center;
    gap: .55rem;
    background: var(--green);
    color: var(--cream);
    border-radius: 100px;
    padding: .6rem 1.25rem;
    font-size: .92rem;
    text-decoration: none;
    font-family: 'TT Norms Pro', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-weight: 500;
    transition: background .2s, transform .15s;
    letter-spacing: .01em;
  }
  .lg-kontakti .qc-pill:hover { background: #1e4436; transform: translateY(-2px); }
  .lg-kontakti .qc-pill svg { flex-shrink: 0; }

  /* ── Address pill ── */
  .lg-kontakti .address-row {
    display: flex;
    align-items: flex-start;
    gap: .6rem;
    margin-bottom: 3rem;
    font-size: .95rem;
    color: var(--muted);
  }
  .lg-kontakti .address-row svg { margin-top: 2px; flex-shrink: 0; }

  /* ── Section cards ── */
  .lg-kontakti .section-card {
    background: white;
    border-radius: var(--radius);
    overflow: hidden;
    margin-bottom: 1.25rem;
    box-shadow: 0 2px 16px rgba(42,94,74,.07);
    border: 1.5px solid rgba(42,94,74,.08);
