    .lg-kontakti .card-inner { padding: 0 1.25rem 1.4rem; }
    .lg-kontakti .fig-1 { width: 210px; }
    .lg-kontakti .fig-2 { width: 160px; }
    .lg-kontakti .fig-3, .lg-kontakti .fig-4 { display: none; }
  }

sections.js:
// Contacts dropdowns — close others when opening
function toggle(btn) {
  const body = btn.nextElementSibling;
  const isOpen = body.classList.contains('open');
  document.querySelectorAll('.card-body.open').forEach(b => {
    b.classList.remove('open');
    b.previousElementSibling.classList.remove('open');
    b.previousElementSibling.setAttribute('aria-expanded', 'false');
  });
  if (!isOpen) {
    body.classList.add('open');
    btn.classList.add('open');
    btn.setAttribute('aria-expanded', 'true');
  }
}
// Rekvizīti dropdowns — each opens independently
function toggleRek(btn) {
  const body = btn.nextElementSibling;
  const isOpen = body.classList.contains('open');
  body.classList.toggle('open', !isOpen);
  btn.classList.toggle('open', !isOpen);
  btn.setAttribute('aria-expanded', String(!isOpen));
}

