/* === KULTŪRAS PATNIS – SKATUVE LANDING === */
/* prefix: ku- (kultūras/skatuve) */

.lg-kulturas-patnis-adazos {
  --ku-gold:    #F1B01D;
  --ku-green:   #2A5E4A;
  --ku-cream:   #FFF8EE;
  --ku-orange:  #FF9068;
  --ku-blue:    #8E9DFF;
  --ku-dark:    #1A1A18;
  --ku-muted:   #5C5C50;
  --ku-gold-light: #FDF3D0;
  --ku-green-light: #EAF2EE;

  --ku-font-display: 'Figtree', 'Helvetica Neue', sans-serif;
  --ku-font-body:    'Source Serif 4', Georgia, serif;

  --ku-radius: 16px;
  --ku-radius-sm: 10px;
  --ku-shadow: 0 4px 24px rgba(42,94,74,0.10);
  --ku-shadow-hover: 0 8px 36px rgba(42,94,74,0.16);
}

.lg-kulturas-patnis-adazos *, .lg-kulturas-patnis-adazos *::before, .lg-kulturas-patnis-adazos *::after { box-sizing: border-box; margin: 0; padding: 0; }

.lg-kulturas-patnis-adazos {
  font-family: var(--ku-font-body);
  background: var(--ku-cream);
  color: var(--ku-dark);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── UTILITY ── */
.lg-kulturas-patnis-adazos .ku-container {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 24px;
}
.lg-kulturas-patnis-adazos .ku-section {
  padding: 80px 0;
}
.lg-kulturas-patnis-adazos .ku-eyebrow {
  font-family: var(--ku-font-display);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ku-gold);
  margin-bottom: 12px;
}
.lg-kulturas-patnis-adazos .ku-heading {
  font-family: var(--ku-font-display);
  font-weight: 800;
  line-height: 1.15;
  color: var(--ku-green);
}
.lg-kulturas-patnis-adazos .ku-heading--xl  { font-size: clamp(2.2rem, 5vw, 3.6rem); }
.lg-kulturas-patnis-adazos .ku-heading--lg  { font-size: clamp(1.7rem, 3.5vw, 2.6rem); }
.lg-kulturas-patnis-adazos .ku-heading--md  { font-size: clamp(1.3rem, 2.5vw, 1.9rem); }
.lg-kulturas-patnis-adazos .ku-lead {
  font-size: clamp(1.05rem, 2vw, 1.2rem);
  color: var(--ku-muted);
  line-height: 1.75;
  max-width: 600px;
}

/* ── BUTTONS ── */
.lg-kulturas-patnis-adazos .ku-btn {
  display: inline-block;
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1rem;
  border-radius: 50px;
  padding: 14px 36px;
  cursor: pointer;
  text-decoration: none;
  border: none;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.lg-kulturas-patnis-adazos .ku-btn:hover { transform: translateY(-2px); box-shadow: var(--ku-shadow-hover); }
.lg-kulturas-patnis-adazos .ku-btn--gold { background: var(--ku-gold); color: var(--ku-dark); }
.lg-kulturas-patnis-adazos .ku-btn--green { background: var(--ku-green); color: var(--ku-cream); }
.lg-kulturas-patnis-adazos .ku-btn--outline { background: transparent; border: 2px solid var(--ku-green); color: var(--ku-green); }
.lg-kulturas-patnis-adazos .ku-btn--lg { padding: 18px 48px; font-size: 1.1rem; }

/* ══════════════════════════════════════
   1. HERO
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-hero {
  background: var(--ku-green);
  color: var(--ku-cream);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}
.lg-kulturas-patnis-adazos .ku-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 85% 50%, rgba(241,176,29,0.12) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 10% 80%, rgba(241,176,29,0.08) 0%, transparent 60%);
  pointer-events: none;
}
/* decorative arc */
.lg-kulturas-patnis-adazos .ku-hero::after {
  content: '';
  position: absolute;
  bottom: -60px; left: -80px;
  width: 320px; height: 320px;
  border-radius: 50%;
  border: 48px solid rgba(241,176,29,0.10);
  pointer-events: none;
}

.lg-kulturas-patnis-adazos .ku-hero__inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.lg-kulturas-patnis-adazos .ku-hero__label {
  font-family: var(--ku-font-display);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ku-gold);
  margin-bottom: 16px;
}
.lg-kulturas-patnis-adazos .ku-hero__badge {
  display: inline-block;
  font-family: var(--ku-font-display);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ku-dark);
  background: var(--ku-gold);
  padding: 6px 16px;
  border-radius: 50px;
  margin-bottom: 18px;
}
.lg-kulturas-patnis-adazos .ku-hero__title {
  font-family: var(--ku-font-display);
  font-weight: 800;
  font-size: clamp(2.6rem, 5.5vw, 4.2rem);
  line-height: 1.08;
  color: var(--ku-cream);
  margin-bottom: 20px;
}
.lg-kulturas-patnis-adazos .ku-hero__title em {
  font-style: normal;
  color: var(--ku-gold);
}
.lg-kulturas-patnis-adazos .ku-hero__sub {
  font-family: var(--ku-font-body);
  font-size: clamp(1rem, 1.8vw, 1.15rem);
  color: rgba(255,248,238,0.75);
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 480px;
}
.lg-kulturas-patnis-adazos .ku-hero__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 40px;
}
.lg-kulturas-patnis-adazos .ku-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(241,176,29,0.15);
  border: 1.5px solid rgba(241,176,29,0.35);
  color: var(--ku-gold);
  font-family: var(--ku-font-display);
  font-weight: 600;
  font-size: 0.9rem;
  padding: 8px 18px;
  border-radius: 50px;
}
.lg-kulturas-patnis-adazos .ku-pill .ku-pill__icon { font-size: 1.1rem; }

.lg-kulturas-patnis-adazos .ku-hero__visual {
  display: flex;
  justify-content: center;
  align-items: center;
}
.lg-kulturas-patnis-adazos .ku-hero__stage {
  position: relative;
  width: 100%;
  max-width: 400px;
}
/* Abstract stage curtain graphic */
.lg-kulturas-patnis-adazos .ku-stage-art {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 50% 50% 8px 8px / 60% 60% 8px 8px;
  background: linear-gradient(160deg, rgba(241,176,29,0.18) 0%, rgba(241,176,29,0.05) 100%);
  border: 2px solid rgba(241,176,29,0.25);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 48px 32px;
}
.lg-kulturas-patnis-adazos .ku-stage-art__spotlight {
  width: 80px; height: 80px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(241,176,29,0.7) 0%, rgba(241,176,29,0.15) 60%, transparent 80%);
  margin-bottom: 4px;
}
.lg-kulturas-patnis-adazos .ku-stage-art__text {
  font-family: var(--ku-font-display);
  font-weight: 800;
  font-size: 1.4rem;
  color: var(--ku-cream);
  text-align: center;
  letter-spacing: -0.01em;
}
.lg-kulturas-patnis-adazos .ku-stage-art__sub {
  font-family: var(--ku-font-body);
  font-size: 0.85rem;
  color: rgba(255,248,238,0.55);
  text-align: center;
}

/* ══════════════════════════════════════
   2. INTRO
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-intro {
  background: var(--ku-cream);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-intro__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.lg-kulturas-patnis-adazos .ku-intro__quote {
  font-family: var(--ku-font-display);
  font-size: clamp(1.5rem, 2.8vw, 2.1rem);
  font-weight: 700;
  line-height: 1.3;
  color: var(--ku-green);
  position: relative;
  padding-left: 28px;
}
.lg-kulturas-patnis-adazos .ku-intro__quote::before {
  content: '';
  position: absolute;
  left: 0; top: 4px; bottom: 4px;
  width: 5px;
  background: var(--ku-gold);
  border-radius: 4px;
}
.lg-kulturas-patnis-adazos .ku-intro__body p {
  font-size: 1.05rem;
  color: var(--ku-muted);
  line-height: 1.8;
  margin-bottom: 16px;
}
.lg-kulturas-patnis-adazos .ku-intro__body p:last-child { margin-bottom: 0; }
.lg-kulturas-patnis-adazos .ku-intro__body strong { color: var(--ku-dark); font-weight: 600; }

/* ══════════════════════════════════════
   3. IEGUVUMI (benefits grid)
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-benefits {
  background: var(--ku-green);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-benefits__head {
  text-align: center;
  margin-bottom: 56px;
}
.lg-kulturas-patnis-adazos .ku-benefits__head .ku-eyebrow { color: var(--ku-gold); }
.lg-kulturas-patnis-adazos .ku-benefits__head .ku-heading { color: var(--ku-cream); }

.lg-kulturas-patnis-adazos .ku-benefits__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.lg-kulturas-patnis-adazos .ku-benefit-card {
  background: rgba(255,248,238,0.06);
  border: 1.5px solid rgba(255,248,238,0.12);
  border-radius: var(--ku-radius);
  padding: 32px 28px;
  transition: background 0.2s ease, border-color 0.2s ease;
}
.lg-kulturas-patnis-adazos .ku-benefit-card:hover {
  background: rgba(241,176,29,0.10);
  border-color: rgba(241,176,29,0.30);
}
.lg-kulturas-patnis-adazos .ku-benefit-card__num {
  font-family: var(--ku-font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(241,176,29,0.55);
  margin-bottom: 16px;
}
.lg-kulturas-patnis-adazos .ku-benefit-card__title {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--ku-cream);
  margin-bottom: 10px;
}
.lg-kulturas-patnis-adazos .ku-benefit-card__body {
  font-size: 0.95rem;
  color: rgba(255,248,238,0.65);
  line-height: 1.7;
}

/* ══════════════════════════════════════
   4. NODARBĪBAS
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-lessons {
  background: var(--ku-gold-light);
  padding: 88px 0;
  position: relative;
  overflow: hidden;
}
.lg-kulturas-patnis-adazos .ku-lessons::before {
  content: '';
  position: absolute;
  top: -120px; right: -120px;
  width: 400px; height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(241,176,29,0.18) 0%, transparent 70%);
  pointer-events: none;
}
.lg-kulturas-patnis-adazos .ku-lessons__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: start;
  position: relative;
  z-index: 1;
}
.lg-kulturas-patnis-adazos .ku-lessons__content .ku-heading { margin-bottom: 20px; }
.lg-kulturas-patnis-adazos .ku-lessons__lead {
  font-size: 1.05rem;
  color: var(--ku-muted);
  line-height: 1.75;
  margin-bottom: 32px;
  font-style: italic;
}
.lg-kulturas-patnis-adazos .ku-lessons__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.lg-kulturas-patnis-adazos .ku-lessons__list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 1rem;
  color: var(--ku-dark);
  line-height: 1.5;
}
.lg-kulturas-patnis-adazos .ku-lessons__list li::before {
  content: '';
  flex-shrink: 0;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--ku-gold);
  margin-top: 7px;
}

/* aizkulises visual */
.lg-kulturas-patnis-adazos .ku-lessons__visual {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.lg-kulturas-patnis-adazos .ku-backstage-card {
  background: var(--ku-cream);
  border-radius: var(--ku-radius);
  padding: 24px 28px;
  box-shadow: var(--ku-shadow);
}
.lg-kulturas-patnis-adazos .ku-backstage-card__label {
  font-family: var(--ku-font-display);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ku-gold);
  margin-bottom: 8px;
}
.lg-kulturas-patnis-adazos .ku-backstage-card__text {
  font-family: var(--ku-font-display);
  font-size: 1rem;
  font-weight: 600;
  color: var(--ku-green);
}

/* ══════════════════════════════════════
   5. PROGRAMMAS
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-programs {
  background: var(--ku-cream);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-programs__head {
  text-align: center;
  margin-bottom: 16px;
}
.lg-kulturas-patnis-adazos .ku-programs__intro {
  text-align: center;
  font-size: 1rem;
  color: var(--ku-muted);
  max-width: 520px;
  margin: 0 auto 52px;
  line-height: 1.7;
}

.lg-kulturas-patnis-adazos .ku-programs__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 44px;
}
.lg-kulturas-patnis-adazos .ku-program-card {
  border-radius: var(--ku-radius);
  padding: 36px 28px 32px;
  border: 2px solid transparent;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
  display: flex;
  flex-direction: column;
}
.lg-kulturas-patnis-adazos .ku-program-card:hover {
  box-shadow: var(--ku-shadow-hover);
}
.lg-kulturas-patnis-adazos .ku-program-card--1 {
  background: var(--ku-green);
  border-color: var(--ku-green);
}
.lg-kulturas-patnis-adazos .ku-program-card--2 {
  background: var(--ku-gold-light);
  border-color: rgba(241,176,29,0.35);
}
.lg-kulturas-patnis-adazos .ku-program-card--3 {
  background: var(--ku-green-light);
  border-color: rgba(42,94,74,0.15);
}
.lg-kulturas-patnis-adazos .ku-program-card__tag {
  display: inline-block;
  font-family: var(--ku-font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 50px;
  margin-bottom: 20px;
  align-self: flex-start;
}
.lg-kulturas-patnis-adazos .ku-program-card--1 .ku-program-card__tag { background: rgba(241,176,29,0.20); color: var(--ku-gold); }
.lg-kulturas-patnis-adazos .ku-program-card--2 .ku-program-card__tag { background: rgba(241,176,29,0.30); color: #8B6200; }
.lg-kulturas-patnis-adazos .ku-program-card--3 .ku-program-card__tag { background: rgba(42,94,74,0.12); color: var(--ku-green); }

.lg-kulturas-patnis-adazos .ku-program-card__title {
  font-family: var(--ku-font-display);
  font-weight: 800;
  font-size: 1.2rem;
  margin-bottom: 14px;
  line-height: 1.2;
}
.lg-kulturas-patnis-adazos .ku-program-card--1 .ku-program-card__title { color: var(--ku-cream); }
.lg-kulturas-patnis-adazos .ku-program-card--2 .ku-program-card__title { color: var(--ku-dark); }
.lg-kulturas-patnis-adazos .ku-program-card--3 .ku-program-card__title { color: var(--ku-dark); }

.lg-kulturas-patnis-adazos .ku-program-card__body {
  font-size: 0.95rem;
  line-height: 1.7;
  flex: 1;
}
.lg-kulturas-patnis-adazos .ku-program-card--1 .ku-program-card__body { color: rgba(255,248,238,0.75); }
.lg-kulturas-patnis-adazos .ku-program-card--2 .ku-program-card__body { color: var(--ku-muted); }
.lg-kulturas-patnis-adazos .ku-program-card--3 .ku-program-card__body { color: var(--ku-muted); }

.lg-kulturas-patnis-adazos .ku-programs__cta { text-align: center; }

/* ══════════════════════════════════════
   6. AIZKULISES (process)
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-process {
  background: var(--ku-green);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-process__head {
  margin-bottom: 16px;
}
.lg-kulturas-patnis-adazos .ku-process__head .ku-eyebrow { color: var(--ku-gold); }
.lg-kulturas-patnis-adazos .ku-process__head .ku-heading { color: var(--ku-cream); }
.lg-kulturas-patnis-adazos .ku-process__lead {
  font-size: 1rem;
  color: rgba(255,248,238,0.65);
  max-width: 540px;
  line-height: 1.75;
  margin-bottom: 52px;
}
.lg-kulturas-patnis-adazos .ku-process__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: start;
}
.lg-kulturas-patnis-adazos .ku-process__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.lg-kulturas-patnis-adazos .ku-process__list li {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  font-size: 0.98rem;
  color: rgba(255,248,238,0.80);
  line-height: 1.5;
}
.lg-kulturas-patnis-adazos .ku-process__list li::before {
  content: '';
  flex-shrink: 0;
  width: 7px; height: 7px;
  border-radius: 50%;
  background: var(--ku-gold);
  margin-top: 8px;
}

/* flow diagram */
.lg-kulturas-patnis-adazos .ku-flow {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.lg-kulturas-patnis-adazos .ku-flow__step {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 24px;
  background: rgba(255,248,238,0.05);
  border: 1.5px solid rgba(255,248,238,0.10);
  border-radius: var(--ku-radius-sm);
  margin-bottom: 2px;
  transition: background 0.2s;
}
.lg-kulturas-patnis-adazos .ku-flow__step:hover {
  background: rgba(241,176,29,0.10);
  border-color: rgba(241,176,29,0.25);
}
.lg-kulturas-patnis-adazos .ku-flow__icon {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: rgba(241,176,29,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}
.lg-kulturas-patnis-adazos .ku-flow__label {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1rem;
  color: var(--ku-cream);
}
.lg-kulturas-patnis-adazos .ku-flow__desc {
  font-size: 0.85rem;
  color: rgba(255,248,238,0.55);
}
.lg-kulturas-patnis-adazos .ku-flow__arrow {
  text-align: center;
  color: rgba(241,176,29,0.45);
  font-size: 1.1rem;
  line-height: 1;
  padding: 2px 0;
}

/* ══════════════════════════════════════
   7. KĀPĒC KULTŪRAS PATNIS
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-why {
  background: var(--ku-cream);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-why__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.lg-kulturas-patnis-adazos .ku-why__content .ku-heading { margin-bottom: 28px; }
.lg-kulturas-patnis-adazos .ku-why__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.lg-kulturas-patnis-adazos .ku-why__list li {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  font-size: 1rem;
  color: var(--ku-dark);
  line-height: 1.55;
}
.lg-kulturas-patnis-adazos .ku-why__check {
  flex-shrink: 0;
  width: 24px; height: 24px;
  border-radius: 50%;
  background: var(--ku-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}
.lg-kulturas-patnis-adazos .ku-why__check::after {
  content: '✓';
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 0.75rem;
  color: var(--ku-dark);
}

.lg-kulturas-patnis-adazos .ku-why__badge {
  background: var(--ku-green);
  border-radius: var(--ku-radius);
  padding: 48px 40px;
  text-align: center;
  color: var(--ku-cream);
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}
.lg-kulturas-patnis-adazos .ku-why__badge-num {
  font-family: var(--ku-font-display);
  font-size: 4rem;
  font-weight: 800;
  color: var(--ku-gold);
  line-height: 1;
}
.lg-kulturas-patnis-adazos .ku-why__badge-label {
  font-size: 1rem;
  color: rgba(255,248,238,0.75);
  line-height: 1.55;
  max-width: 200px;
}
.lg-kulturas-patnis-adazos .ku-why__badge-tagline {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--ku-cream);
  margin-top: 8px;
}

/* ══════════════════════════════════════
   8. PRAKTISKĀ INFO
══════════════════════════════════════ */
.lg-kulturas-patnis-adazos .ku-info {
  background: var(--ku-gold-light);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-info__head {
  text-align: center;
  margin-bottom: 52px;
}
.lg-kulturas-patnis-adazos .ku-info__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 52px;
}
.lg-kulturas-patnis-adazos .ku-info__grid--3 {
  grid-template-columns: repeat(3, 1fr);
}
.lg-kulturas-patnis-adazos .ku-info-block {
  background: var(--ku-cream);
  border-radius: var(--ku-radius);
  padding: 28px 24px;
  box-shadow: var(--ku-shadow);
}
.lg-kulturas-patnis-adazos .ku-info-block__icon {
  font-size: 1.6rem;
  margin-bottom: 12px;
}
.lg-kulturas-patnis-adazos .ku-info-block__label {
  font-family: var(--ku-font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ku-gold);
  margin-bottom: 6px;
}
.lg-kulturas-patnis-adazos .ku-info-block__value {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1rem;
  color: var(--ku-green);
  line-height: 1.4;
}
.lg-kulturas-patnis-adazos .ku-info-block__note {
  font-size: 0.85rem;
  color: var(--ku-muted);
  margin-top: 4px;
  line-height: 1.5;
}
.lg-kulturas-patnis-adazos .ku-info__cta { text-align: center; }

/* ── PAR KULTŪRAS PATNI ĀDAŽOS ── */
.lg-kulturas-patnis-adazos .ku-about-adazi {
  background: var(--ku-cream);
}
.lg-kulturas-patnis-adazos .ku-about-adazi__inner {
  max-width: 720px;
}
.lg-kulturas-patnis-adazos .ku-about-adazi__title {
  margin-bottom: 20px;
}
.lg-kulturas-patnis-adazos .ku-about-adazi__lead {
  font-size: 1.05rem;
  color: var(--ku-muted);
  line-height: 1.8;
  margin-bottom: 28px;
}
.lg-kulturas-patnis-adazos .ku-about-adazi__note {
  font-family: var(--ku-font-display);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--ku-dark);
  margin-bottom: 16px;
}
.lg-kulturas-patnis-adazos .ku-about-adazi__pills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.lg-kulturas-patnis-adazos .ku-about-adazi__pills .ku-pill {
  background: rgba(241,176,29,0.12);
  border: 1.5px solid rgba(241,176,29,0.30);
  color: var(--ku-dark);
}

/* ── LOCATION / DEPT BLOCK ── */
.lg-kulturas-patnis-adazos .ku-location-block {
  background: var(--ku-cream);
  border: 2px solid rgba(42,94,74,0.10);
  border-radius: var(--ku-radius);
  overflow: hidden;
  margin-bottom: 44px;
  box-shadow: var(--ku-shadow);
}
.lg-kulturas-patnis-adazos .ku-location-block__header {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--ku-green);
  padding: 16px 28px;
}
.lg-kulturas-patnis-adazos .ku-location-block__pin { font-size: 1rem; }
.lg-kulturas-patnis-adazos .ku-location-block__city {
  font-family: var(--ku-font-display);
  font-weight: 800;
  font-size: 1rem;
  color: var(--ku-cream);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.lg-kulturas-patnis-adazos .ku-dept-group {
  border-top: 1px solid rgba(42,94,74,0.08);
}
.lg-kulturas-patnis-adazos .ku-dept-group:first-child {
  border-top: none;
}
.lg-kulturas-patnis-adazos .ku-dept-group__title {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--ku-green);
  padding: 18px 28px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(42,94,74,0.04);
  border-bottom: 1px solid rgba(42,94,74,0.07);
}
.lg-kulturas-patnis-adazos .ku-dept-group__programs {
  display: flex;
  flex-direction: column;
}
.lg-kulturas-patnis-adazos .ku-dept-program-wrap {
  border-bottom: 1px solid rgba(42,94,74,0.05);
}
.lg-kulturas-patnis-adazos .ku-dept-program-wrap:last-child { border-bottom: none; }

.lg-kulturas-patnis-adazos .ku-dept-program {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font: inherit;
  padding: 14px 28px 14px 44px;
  transition: background 0.15s;
}
.lg-kulturas-patnis-adazos .ku-dept-program:hover { background: rgba(241,176,29,0.05); }
.lg-kulturas-patnis-adazos .ku-dept-program--highlight { background: rgba(241,176,29,0.06); }
.lg-kulturas-patnis-adazos .ku-dept-program--highlight:hover { background: rgba(241,176,29,0.11); }

.lg-kulturas-patnis-adazos .ku-dept-program__main {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.lg-kulturas-patnis-adazos .ku-dept-program__more {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.lg-kulturas-patnis-adazos .ku-dept-program__more-text {
  font-family: var(--ku-font-display);
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ku-green);
  white-space: nowrap;
}
.lg-kulturas-patnis-adazos .ku-dept-program__chevron {
  flex-shrink: 0;
  font-size: 1.1rem;
  color: var(--ku-green);
  transition: transform 0.2s ease;
  line-height: 1;
}
.lg-kulturas-patnis-adazos .ku-dept-program[aria-expanded="true"] .ku-dept-program__chevron {
  transform: rotate(180deg);
}

.lg-kulturas-patnis-adazos .ku-dept-program__panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.25s ease;
}
.lg-kulturas-patnis-adazos .ku-dept-program__panel.ku-is-open {
  max-height: 1200px;
}
.lg-kulturas-patnis-adazos .ku-dept-program__desc {
  font-family: var(--ku-font-body);
  font-size: 0.92rem;
  color: var(--ku-muted);
  line-height: 1.7;
  padding: 0 28px 12px 44px;
}
.lg-kulturas-patnis-adazos .ku-dept-program__panel .ku-dept-program__desc:last-child {
  padding-bottom: 18px;
}
.lg-kulturas-patnis-adazos .ku-dept-program__list {
  list-style: none;
  padding: 0 28px 14px 44px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.lg-kulturas-patnis-adazos .ku-dept-program__list li {
  font-family: var(--ku-font-body);
  font-size: 0.92rem;
  color: var(--ku-muted);
  line-height: 1.6;
  padding-left: 16px;
  position: relative;
}
.lg-kulturas-patnis-adazos .ku-dept-program__list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 9px;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--ku-gold);
}
.lg-kulturas-patnis-adazos .ku-dept-program__name {
  font-family: var(--ku-font-display);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--ku-dark);
}
.lg-kulturas-patnis-adazos .ku-dept-program__tag {
  font-family: var(--ku-font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ku-green);
  background: rgba(42,94,74,0.08);
  padding: 3px 10px;
  border-radius: 50px;
}
.lg-kulturas-patnis-adazos .ku-dept-program--highlight .ku-dept-program__tag {
  color: #8B6200;
  background: rgba(241,176,29,0.22);
}
.lg-kulturas-patnis-adazos .ku-dept-program--highlight .ku-dept-program__tag--new,
.lg-kulturas-patnis-adazos .ku-dept-program__tag--new {
  color: var(--ku-dark);
  background: var(--ku-gold);
}
.lg-kulturas-patnis-adazos .ku-dept-program__note {
  font-size: 0.82rem;
  color: var(--ku-muted);
  font-style: italic;
}
.lg-kulturas-patnis-adazos .ku-dept-program__subhead {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--ku-green);
  padding: 4px 28px 8px 44px;
}

/* ── CENAS / DALĪBAS MAKSA ── */
.lg-kulturas-patnis-adazos .ku-prices {
  background: var(--ku-cream);
  padding: 88px 0;
}
.lg-kulturas-patnis-adazos .ku-prices__head {
  text-align: center;
  margin-bottom: 52px;
}
.lg-kulturas-patnis-adazos .ku-prices__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 920px;
  margin: 0 auto 24px;
}
.lg-kulturas-patnis-adazos .ku-price-card {
  background: var(--ku-cream);
  border: 2px solid rgba(42,94,74,0.12);
  border-radius: var(--ku-radius);
  padding: 44px 28px 36px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  position: relative;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.lg-kulturas-patnis-adazos .ku-price-card:hover {
  box-shadow: var(--ku-shadow-hover);
  border-color: rgba(241,176,29,0.40);
}
.lg-kulturas-patnis-adazos .ku-price-card__tag {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--ku-font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ku-gold);
  background: rgba(241,176,29,0.14);
  padding: 4px 12px;
  border-radius: 50px;
}
.lg-kulturas-patnis-adazos .ku-price-card__label {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--ku-green);
  line-height: 1.25;
}
.lg-kulturas-patnis-adazos .ku-price-card__amount {
  font-family: var(--ku-font-display);
  font-weight: 800;
  font-size: 2.4rem;
  color: var(--ku-dark);
  line-height: 1;
}
.lg-kulturas-patnis-adazos .ku-price-card__period {
  font-family: var(--ku-font-display);
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ku-muted);
}
.lg-kulturas-patnis-adazos .ku-prices__note {
  text-align: center;
  font-size: 0.9rem;
  color: var(--ku-muted);
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.6;
}

/* ── KONTAKTI ── */
.lg-kulturas-patnis-adazos .ku-contact {
  background: var(--ku-green);
  padding: 80px 0;
  color: var(--ku-cream);
}
.lg-kulturas-patnis-adazos .ku-contact__head {
  text-align: center;
  margin-bottom: 40px;
}
.lg-kulturas-patnis-adazos .ku-contact__head .ku-eyebrow { color: var(--ku-gold); }
.lg-kulturas-patnis-adazos .ku-contact__head .ku-heading { color: var(--ku-cream); }
.lg-kulturas-patnis-adazos .ku-contact__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  max-width: 640px;
  margin: 0 auto;
}
.lg-kulturas-patnis-adazos .ku-contact-card {
  background: rgba(255,248,238,0.06);
  border: 1.5px solid rgba(255,248,238,0.12);
  border-radius: var(--ku-radius);
  padding: 28px 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.lg-kulturas-patnis-adazos .ku-contact-card__icon { font-size: 1.6rem; }
.lg-kulturas-patnis-adazos .ku-contact-card__label {
  font-family: var(--ku-font-display);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ku-gold);
}
.lg-kulturas-patnis-adazos .ku-contact-card__value {
  font-family: var(--ku-font-display);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--ku-cream);
  min-height: 1.4em;
}
.lg-kulturas-patnis-adazos .ku-contact-card__value a {
  color: var(--ku-cream);
  text-decoration: none;
}
.lg-kulturas-patnis-adazos .ku-contact-card__value a:hover { color: var(--ku-gold); }

/* ══════════════════════════════════════
   RESPONSIVE
══════════════════════════════════════ */
@media (max-width: 900px) {
  .lg-kulturas-patnis-adazos .ku-hero__inner,
  .lg-kulturas-patnis-adazos .ku-intro__grid,
  .lg-kulturas-patnis-adazos .ku-lessons__inner,
  .lg-kulturas-patnis-adazos .ku-process__grid,
  .lg-kulturas-patnis-adazos .ku-why__inner {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .lg-kulturas-patnis-adazos .ku-hero__visual { display: none; }
  .lg-kulturas-patnis-adazos .ku-benefits__grid,
  .lg-kulturas-patnis-adazos .ku-programs__grid { grid-template-columns: 1fr; }
  .lg-kulturas-patnis-adazos .ku-prices__grid { grid-template-columns: 1fr; max-width: 380px; }
  .lg-kulturas-patnis-adazos .ku-info__grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 560px) {
  .lg-kulturas-patnis-adazos .ku-section { padding: 56px 0; }
  .lg-kulturas-patnis-adazos .ku-info__grid { grid-template-columns: 1fr; }
  .lg-kulturas-patnis-adazos .ku-contact__grid { grid-template-columns: 1fr; }
  .lg-kulturas-patnis-adazos .ku-btn--lg { padding: 16px 32px; font-size: 1rem; }
}

sections.js:
document.querySelectorAll('.ku-dept-program').forEach(function (btn) {
  btn.addEventListener('click', function () {
    var wrap = btn.closest('.ku-dept-program-wrap');
    var panel = wrap.querySelector('.ku-dept-program__panel');
    var isOpen = btn.getAttribute('aria-expanded') === 'true';
    btn.setAttribute('aria-expanded', String(!isOpen));
    panel.classList.toggle('ku-is-open', !isOpen);
  });
});

sections.css:
.lg-ppms {
    --green: #2A5E4A;
    --green-light: #3a7a60;
    --green-pale: #e8f1ed;
    --cream: #FFF8EE;
    --orange: #FF9068;
    --blue: #8E9DFF;
    --yellow: #F1B01D;
    --yellow-pale: #FEF3D0;
    --text-dark: #1a2e24;
    --text-mid: #4a6557;
    --text-light: #7a9589;
    --radius-lg: 20px;
    --radius-md: 12px;
    --radius-sm: 8px;
  }

  .lg-ppms * { box-sizing: border-box; margin: 0; padding: 0; }

  .lg-ppms {
    background: var(--cream);
    font-family: 'Figtree', 'Helvetica Neue', sans-serif;
    color: var(--text-dark);
    overflow-x: hidden;
  }

  /* ── SVG decorative background ── */
  .lg-ppms .page-bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 0;
    overflow: hidden;
  }
  .lg-ppms { position: relative; }


  .lg-ppms .wrap {
    position: relative;
    z-index: 1;
    max-width: 1080px;
    margin: 0 auto;
    padding: 0 24px;
  }

  /* ── HERO ── */
  .lg-ppms .hero {
    padding: 80px 0 60px;
    position: relative;
  }
  .lg-ppms .hero-tag {
    display: inline-block;
    background: var(--yellow);
    color: var(--text-dark);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 6px 16px;
    border-radius: 100px;
    margin-bottom: 28px;
  }
  .lg-ppms .hero h1 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: clamp(36px, 5vw, 58px);
    font-weight: 600;
    line-height: 1.15;
    color: var(--green);
    max-width: 780px;
    margin-bottom: 28px;
  }
  .lg-ppms .hero h1 em {
    font-style: italic;
    font-weight: 300;
    color: var(--text-mid);
  }
  .lg-ppms .hero-lead {
    font-size: 18px;
    line-height: 1.7;
    color: var(--text-mid);
    max-width: 640px;
    margin-bottom: 16px;
  }
  .lg-ppms .hero-note {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 14px;
    color: var(--text-light);
    margin-bottom: 40px;
  }
  .lg-ppms .hero-note::before {
    content: '';
    display: inline-block;
    width: 20px;
    height: 2px;
    background: var(--yellow);
    border-radius: 2px;
    flex-shrink: 0;
  }
  .lg-ppms .hero-cta {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--green);
    color: #fff;
    font-size: 16px;
    font-weight: 600;
    padding: 16px 32px;
    border-radius: 100px;
    text-decoration: none;
    transition: background 0.2s, transform 0.15s;
  }
  .lg-ppms .hero-cta:hover {
    background: var(--green-light);
    transform: translateY(-1px);
  }
  .lg-ppms .hero-cta svg {
    width: 18px;
    height: 18px;
    stroke: #fff;
    fill: none;
    stroke-width: 2.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  .lg-ppms .hero-date {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-left: 20px;
    font-size: 14px;
    color: var(--text-mid);
    font-weight: 500;
  }
  .lg-ppms .hero-date-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--orange);
    display: inline-block;
    animation: pulse 2s ease-in-out infinite;
  }
  @keyframes pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(0.7); }
  }

  /* ── DIVIDER ── */
  .lg-ppms .divider {
    width: 100%;
    height: 2px;
    background: linear-gradient(90deg, var(--green) 0%, var(--green-pale) 100%);
    border-radius: 2px;
    margin: 0 0 64px;
    opacity: 0.3;
  }

  /* ── INTRO STRIP ── */
  .lg-ppms .intro-strip {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 48px;
    margin-bottom: 80px;
    align-items: center;
  }
  .lg-ppms .intro-strip h2 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: clamp(26px, 3vw, 36px);
    font-weight: 600;
    line-height: 1.3;
    color: var(--green);
    margin-bottom: 20px;
  }
  .lg-ppms .intro-strip p {
    font-size: 16px;
    line-height: 1.75;
    color: var(--text-mid);
    margin-bottom: 14px;
  }
  .lg-ppms .standard-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--green-pale);
    border: 1.5px solid rgba(42,94,74,0.2);
    color: var(--green);
    font-size: 13px;
    font-weight: 600;
    padding: 8px 16px;
    border-radius: 100px;
    margin-top: 8px;
  }
  .lg-ppms .standard-badge svg {
    width: 16px;
    height: 16px;
    stroke: var(--green);
    fill: none;
    stroke-width: 2.5;
  }
  .lg-ppms .intro-visual {
    background: var(--green);
    border-radius: var(--radius-lg);
    padding: 36px 32px;
    color: #fff;
  }
  .lg-ppms .intro-visual-title {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    opacity: 0.6;
    margin-bottom: 24px;
  }
  .lg-ppms .pillars {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  .lg-ppms .pillar {
    display: flex;
    align-items: flex-start;
    gap: 14px;
  }
  .lg-ppms .pillar-icon {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 18px;
  }
  .lg-ppms .pillar-icon.orange { background: rgba(255,144,104,0.2); }
  .lg-ppms .pillar-icon.yellow { background: rgba(241,176,29,0.2); }
  .lg-ppms .pillar-icon.blue { background: rgba(142,157,255,0.2); }
  .lg-ppms .pillar-text strong {
    display: block;
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 3px;
  }
  .lg-ppms .pillar-text span {
    font-size: 13px;
    opacity: 0.65;
    line-height: 1.4;
  }

  /* ── SECTION HEADER ── */
  .lg-ppms .section-header {
    text-align: center;
    margin-bottom: 52px;
  }
  .lg-ppms .section-tag {
    display: inline-block;
    background: var(--yellow-pale);
    color: var(--green);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 5px 14px;
    border-radius: 100px;
    margin-bottom: 16px;
    border: 1px solid rgba(241,176,29,0.35);
  }
  .lg-ppms .section-header h2 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: clamp(26px, 3vw, 38px);
    font-weight: 600;
    color: var(--green);
    line-height: 1.25;
    margin-bottom: 14px;
  }
  .lg-ppms .section-header p {
    font-size: 16px;
    color: var(--text-mid);
    max-width: 560px;
    margin: 0 auto;
    line-height: 1.7;
  }

  /* ── DIENAS KĀRTĪBA ── */
  .lg-ppms .day-schedule {
    margin-bottom: 80px;
  }
  .lg-ppms .day-track {
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
  }
  .lg-ppms .day-track::before {
    content: '';
    position: absolute;
    left: 48px;
    top: 24px;
    bottom: 24px;
    width: 2px;
    background: var(--green-pale);
    border-radius: 2px;
    z-index: 0;
  }
  .lg-ppms .day-block {
    display: grid;
    grid-template-columns: 96px 1fr;
    gap: 0;
    position: relative;
    z-index: 1;
  }
  .lg-ppms .day-block + .day-block {
    margin-top: 0;
  }
  .lg-ppms .day-block-dot {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding-top: 28px;
  }
  .lg-ppms .dot {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 3px solid var(--cream);
    flex-shrink: 0;
    position: relative;
    z-index: 2;
  }
  .lg-ppms .dot.green { background: var(--green); }
  .lg-ppms .dot.orange { background: var(--orange); }
  .lg-ppms .dot.yellow { background: var(--yellow); }
  .lg-ppms .dot.blue { background: var(--blue); }
  .lg-ppms .day-block-card {
    border-radius: var(--radius-lg);
    padding: 28px 32px;
    margin: 8px 0;
    position: relative;
    overflow: hidden;
  }
  .lg-ppms .day-block-card.green-card {
    background: var(--green);
    color: #fff;
  }
  .lg-ppms .day-block-card.orange-card {
    background: #fff4f0;
    border: 1.5px solid rgba(255,144,104,0.3);
  }
  .lg-ppms .day-block-card.yellow-card {
    background: var(--yellow-pale);
    border: 1.5px solid rgba(241,176,29,0.3);
  }
  .lg-ppms .day-block-card.blue-card {
    background: #f0f2ff;
    border: 1.5px solid rgba(142,157,255,0.3);
  }
  .lg-ppms .block-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 8px;
    opacity: 0.6;
  }
  .lg-ppms .block-title {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 22px;
    font-weight: 600;
    margin-bottom: 12px;
    line-height: 1.2;
  }
  .lg-ppms .day-block-card.green-card .block-title { color: #fff; }
  .lg-ppms .day-block-card.green-card .block-label { color: rgba(255,255,255,0.65); }
  .lg-ppms .day-block-card.orange-card .block-title { color: #b84a20; }
  .lg-ppms .day-block-card.orange-card .block-label { color: var(--orange); }
  .lg-ppms .day-block-card.yellow-card .block-title { color: #7a5800; }
  .lg-ppms .day-block-card.yellow-card .block-label { color: #b07a00; }
  .lg-ppms .day-block-card.blue-card .block-title { color: #3a4ea8; }
  .lg-ppms .day-block-card.blue-card .block-label { color: var(--blue); }
  .lg-ppms .block-desc {
    font-size: 15px;
    line-height: 1.65;
    max-width: 640px;
  }
  .lg-ppms .day-block-card.green-card .block-desc { color: rgba(255,255,255,0.8); }
  .lg-ppms .day-block-card.orange-card .block-desc { color: #6b3320; }
  .lg-ppms .day-block-card.yellow-card .block-desc { color: #7a5800; opacity: 0.85; }
  .lg-ppms .day-block-card.blue-card .block-desc { color: #3a4ea8; opacity: 0.85; }

  .lg-ppms .block-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 16px;
  }
  .lg-ppms .chip {
    font-size: 13px;
    font-weight: 500;
    padding: 5px 13px;
    border-radius: 100px;
  }
  .lg-ppms .chip.white { background: rgba(255,255,255,0.15); color: rgba(255,255,255,0.9); }
  .lg-ppms .chip.orange { background: rgba(255,144,104,0.15); color: #b84a20; }
  .lg-ppms .chip.yellow { background: rgba(241,176,29,0.18); color: #7a5800; }
  .lg-ppms .chip.blue { background: rgba(142,157,255,0.2); color: #3a4ea8; }

  /* LAB highlight card */
  .lg-ppms .lab-highlight {
    background: var(--green);
    border-radius: var(--radius-lg);
    padding: 36px 40px;
    margin-top: 12px;
    position: relative;
    overflow: hidden;
  }
  .lg-ppms .lab-highlight::after {
    content: 'LAB';
    position: absolute;
    right: -20px;
    bottom: -30px;
    font-size: 120px;
    font-weight: 800;
    color: rgba(255,255,255,0.05);
    line-height: 1;
    pointer-events: none;
    font-family: 'Figtree', sans-serif;
  }
  .lg-ppms .lab-highlight h3 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 28px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 14px;
    line-height: 1.25;
  }
  .lg-ppms .lab-highlight p {
    color: rgba(255,255,255,0.78);
    font-size: 16px;
    line-height: 1.7;
    max-width: 560px;
    margin-bottom: 24px;
  }
  .lg-ppms .lab-features {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 16px;
  }
  .lg-ppms .lab-feat {
    background: rgba(255,255,255,0.1);
    border-radius: var(--radius-md);
    padding: 16px 18px;
  }
  .lg-ppms .lab-feat-icon {
    font-size: 22px;
    margin-bottom: 8px;
  }
  .lg-ppms .lab-feat strong {
    display: block;
    font-size: 13px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 4px;
  }
  .lg-ppms .lab-feat span {
    font-size: 12px;
    color: rgba(255,255,255,0.55);
    line-height: 1.4;
  }

  /* ── ATSLĒGAS VĒRTĪBAS ── */
  .lg-ppms .values-section {
    margin-bottom: 80px;
  }
  .lg-ppms .values-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
  }
  .lg-ppms .value-card {
    background: #fff;
    border-radius: var(--radius-lg);
    padding: 28px 24px;
    border: 1.5px solid rgba(42,94,74,0.1);
    transition: transform 0.2s, border-color 0.2s;
  }
  .lg-ppms .value-card:hover {
    transform: translateY(-3px);
    border-color: rgba(42,94,74,0.25);
  }
  .lg-ppms .value-num {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 42px;
    font-weight: 600;
    color: var(--green);
    opacity: 0.15;
    line-height: 1;
    margin-bottom: 12px;
  }
  .lg-ppms .value-card h3 {
    font-size: 17px;
    font-weight: 600;
    color: var(--green);
    margin-bottom: 10px;
    line-height: 1.3;
  }
  .lg-ppms .value-card p {
    font-size: 14px;
    color: var(--text-mid);
    line-height: 1.65;
  }

  /* ── LABORATORIJAS SADAĻA ── */
  .lg-ppms .labs-section {
    margin-bottom: 80px;
  }
  .lg-ppms .labs-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }
  .lg-ppms .lab-card {
    background: #fff;
    border-radius: var(--radius-lg);
    overflow: hidden;
    border: 1.5px solid rgba(42,94,74,0.1);
    transition: transform 0.2s, border-color 0.2s;
    display: flex;
    flex-direction: column;
  }
  .lg-ppms .lab-card:hover {
    transform: translateY(-3px);
    border-color: rgba(42,94,74,0.25);
  }
  .lg-ppms .lab-card-img {
    width: 100%;
    aspect-ratio: 4/3;
    object-fit: cover;
    display: block;
  }
  .lg-ppms .lab-card-placeholder {
    width: 100%;
    aspect-ratio: 4/3;
    background: var(--green-pale);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    color: var(--text-light);
  }
  .lg-ppms .lab-card-placeholder svg {
    width: 32px;
    height: 32px;
    stroke: var(--text-light);
    fill: none;
    stroke-width: 1.5;
    stroke-linecap: round;
  }
  .lg-ppms .lab-card-placeholder span {
    font-size: 13px;
    font-weight: 500;
  }
  .lg-ppms .lab-card-body {
    padding: 22px 20px 24px;
    flex: 1;
    display: flex;
    flex-direction: column;
  }
  .lg-ppms .lab-card-tag {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--green);
    opacity: 0.6;
    margin-bottom: 8px;
  }
  .lg-ppms .lab-card-title {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 20px;
    font-weight: 600;
    color: var(--green);
    margin-bottom: 10px;
    line-height: 1.25;
  }
  .lg-ppms .lab-card-desc {
    font-size: 14px;
    line-height: 1.65;
    color: var(--text-mid);
    flex: 1;
  }

  @media (max-width: 768px) {
    .lg-ppms .labs-grid { grid-template-columns: 1fr; }
  }

  /* ── CTA SECTION ── */
  .lg-ppms .cta-section {
    background: var(--green);
    border-radius: var(--radius-lg);
    padding: 60px 56px;
    margin-bottom: 80px;
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 48px;
    align-items: center;
    position: relative;
    overflow: hidden;
  }
  .lg-ppms .cta-section::before {
    content: '';
    position: absolute;
    right: -60px;
    top: -60px;
    width: 280px;
    height: 280px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }
  .lg-ppms .cta-section::after {
    content: '';
    position: absolute;
    right: 80px;
    bottom: -80px;
    width: 200px;
    height: 200px;
    border-radius: 50%;
    background: rgba(255,255,255,0.03);
  }
  .lg-ppms .cta-tag {
    display: inline-block;
    background: rgba(241,176,29,0.25);
    color: var(--yellow);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 5px 14px;
    border-radius: 100px;
    margin-bottom: 18px;
  }
  .lg-ppms .cta-section h2 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: clamp(24px, 2.5vw, 34px);
    font-weight: 600;
    color: #fff;
    line-height: 1.25;
    margin-bottom: 14px;
  }
  .lg-ppms .cta-section p {
    color: rgba(255,255,255,0.72);
    font-size: 16px;
    line-height: 1.65;
  }
  .lg-ppms .cta-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--yellow);
    color: var(--text-dark);
    font-size: 16px;
    font-weight: 700;
    padding: 18px 36px;
    border-radius: 100px;
    text-decoration: none;
    white-space: nowrap;
    transition: background 0.2s, transform 0.15s;
    position: relative;
    z-index: 1;
  }
  .lg-ppms .cta-btn:hover {
    background: #e8a500;
    transform: translateY(-2px);
  }
  .lg-ppms .cta-btn svg {
    width: 18px;
    height: 18px;
    stroke: var(--text-dark);
    fill: none;
    stroke-width: 2.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* ── RESPONSIVE ── */
  @media (max-width: 768px) {
    .lg-ppms .intro-strip { grid-template-columns: 1fr; }
    .lg-ppms .values-grid { grid-template-columns: 1fr 1fr; }
    .lg-ppms .cta-section { grid-template-columns: 1fr; padding: 40px 28px; }
    .lg-ppms .day-track::before { left: 36px; }
    .lg-ppms .day-block { grid-template-columns: 72px 1fr; }
    .lg-ppms .day-block-card { padding: 22px 20px; }
    .lg-ppms .hero-date { display: none; }
  }
  @media (max-width: 520px) {
    .lg-ppms .values-grid { grid-template-columns: 1fr; }
  }

.lg-makslu-skola-maksla {
  --green: #2A5E4A;
  --cream: #FFF8EE;
  --gold: #F1B01D;
}
.lg-makslu-skola-maksla .art-page-wrapper {
  position: relative;
  background: var(--cream);
  overflow: visible;
  isolation: isolate;
}
.lg-makslu-skola-maksla .art-figures-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: visible;
}
.lg-makslu-skola-maksla .art-fig { position: absolute; opacity: 0.13; }
.lg-makslu-skola-maksla .art-fig-anim-2 {
  width: 420px; top: -60px; left: -80px;
  transform: rotate(-18deg);
  animation: artFloat1 18s ease-in-out infinite;
}
.lg-makslu-skola-maksla .art-fig-anim-5 {
  width: 340px; bottom: 40px; right: -60px;
  transform: rotate(12deg);
  animation: artFloat2 22s ease-in-out infinite;
}
.lg-makslu-skola-maksla .art-fig-anim-6 {
  width: 300px; top: 45%; left: -40px;
  transform: rotate(5deg);
  animation: artFloat3 26s ease-in-out infinite;
}
.lg-makslu-skola-maksla .art-fig-anim-1 {
  width: 260px; top: 120px; right: -70px;
  transform: rotate(20deg);
  animation: artFloat4 20s ease-in-out infinite;
}
@keyframes artFloat1 { 0%,100%{transform:rotate(-18deg) translateY(0)} 50%{transform:rotate(-14deg) translateY(18px)} }
@keyframes artFloat2 { 0%,100%{transform:rotate(12deg) translateY(0)} 50%{transform:rotate(8deg) translateY(-22px)} }
@keyframes artFloat3 { 0%,100%{transform:rotate(5deg) translateY(0)} 50%{transform:rotate(9deg) translateY(14px)} }
@keyframes artFloat4 { 0%,100%{transform:rotate(20deg) translateY(0)} 50%{transform:rotate(16deg) translateY(20px)} }
.lg-makslu-skola-maksla .art-page {
  position: relative;
  z-index: 2;
  max-width: 860px;
  margin: 0 auto;
  padding: 5rem 3rem 6rem;
  font-family: 'Source Serif 4', Georgia, serif;
  color: var(--green);
}
.lg-makslu-skola-maksla .kp-label {
  display: inline-block;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--green);
  background: var(--gold);
  padding: 0.3rem 0.75rem;
  border-radius: 2px;
  margin-bottom: 2rem;
}
.lg-makslu-skola-maksla .art-hero {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 2rem;
  align-items: center;
  margin-bottom: 3rem;
}
.lg-makslu-skola-maksla .art-title {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(2.3rem, 4.5vw, 3.6rem);
  line-height: 1.03;
  letter-spacing: -0.03em;
  color: var(--green);
  margin: 0 0 1.5rem;
}
.lg-makslu-skola-maksla .art-intro, .lg-makslu-skola-maksla .art-page p {
  font-size: 1.05rem;
  line-height: 1.78;
  color: rgba(42,94,74,0.82);
}
.lg-makslu-skola-maksla .art-btn {
  display: inline-block;
  margin-top: 1.4rem;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-decoration: none;
  color: var(--green) !important;
  background: var(--gold);
  padding: 0.85rem 1.25rem;
  border-radius: 4px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.lg-makslu-skola-maksla .art-btn:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(42,94,74,0.16); }
.lg-makslu-skola-maksla .art-btn.dark { background: var(--green); color: var(--cream) !important; }
.lg-makslu-skola-maksla .divider { width: 48px; height: 3px; background: var(--gold); border-radius: 2px; margin: 3rem 0; }
.lg-makslu-skola-maksla .art-image {
  min-height: 320px;
  border: 2px dashed rgba(241,176,29,0.9);
  background: rgba(255,248,238,0.7);
  color: rgba(42,94,74,0.55);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 1.5rem;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.lg-makslu-skola-maksla .art-image.small { min-height: 260px; }
.lg-makslu-skola-maksla .art-image.art-image-photo {
  padding: 0;
  border: none;
  overflow: hidden;
}
.lg-makslu-skola-maksla .art-image.art-image-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 6px;
  display: block;
}
.lg-makslu-skola-maksla .art-two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  margin: 3rem 0 4rem;
}
.lg-makslu-skola-maksla .art-two-col h2, .lg-makslu-skola-maksla .art-quote h2, .lg-makslu-skola-maksla .art-cta h2 {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(1.7rem, 3vw, 2.35rem);
  line-height: 1.08;
  letter-spacing: -0.025em;
  color: var(--green);
  margin: 0 0 1.2rem;
}
.lg-makslu-skola-maksla .art-block { margin: 4rem 0; }
.lg-makslu-skola-maksla .choose-label {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(42,94,74,0.45);
  margin-bottom: 1.25rem;
}
.lg-makslu-skola-maksla .art-list-card {
  background: var(--green);
  color: var(--cream);
  border-radius: 6px;
  padding: 2rem 2.25rem;
}
.lg-makslu-skola-maksla .art-list-card ul { columns: 2; margin: 0; padding-left: 1.1rem; }
.lg-makslu-skola-maksla .art-list-card li { margin-bottom: 0.75rem; color: rgba(255,248,238,0.86); line-height: 1.5; }
.lg-makslu-skola-maksla .art-gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-top: 1rem;
}
.lg-makslu-skola-maksla .art-image.gallery { min-height: 190px; }
.lg-makslu-skola-maksla .art-quote {
  background: var(--green);
  border-radius: 6px;
  padding: 2.5rem;
  margin: 4rem 0;
}
