.lg-makslu-skola-maksla .art-cta p { color: rgba(42,94,74,0.78); max-width: 620px; }
@media (max-width: 700px) {
  .lg-makslu-skola-maksla .art-page { padding: 3rem 1.5rem 4rem; }
  .lg-makslu-skola-maksla .art-hero, .lg-makslu-skola-maksla .art-two-col, .lg-makslu-skola-maksla .art-gallery, .lg-makslu-skola-maksla .art-pricing-grid, .lg-makslu-skola-maksla .art-programs-grid { grid-template-columns: 1fr; }
  .lg-makslu-skola-maksla .art-list-card ul { columns: 1; }
