  }
  .lg-pirmsskola-gregora-iela .ps-gregora-page {
    --ps-green: #2A5E4A;
    --ps-cream: #FFF8EE;
    --ps-orange: #FF9068;
    --ps-blue: #8E9DFF;
    --ps-gold: #F1B01D;
    position: relative;
    font-family: 'Source Serif 4', Georgia, serif;
    color: var(--ps-green);
    background: var(--ps-cream);
    overflow: hidden;
    border-radius: 0;
  }
  .lg-pirmsskola-gregora-iela .ps-gregora-page * {
    box-sizing: border-box;
  }
  .lg-pirmsskola-gregora-iela .ps-gregora-page h1,
  .lg-pirmsskola-gregora-iela .ps-gregora-page h2,
  .lg-pirmsskola-gregora-iela .ps-gregora-page h3 {
    font-family: 'TT Norms Pro', 'Figtree', 'Helvetica Neue', Arial, sans-serif;
    font-weight: 700;
    margin: 0;
  }
  /* Background figures layer */
  .lg-pirmsskola-gregora-iela .ps-bg-figures {
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    overflow: hidden;
