  .lg-pirmsskola-gregora-iela .ps-fig-1 {
    width: 220px;
    top: 4%;
    left: -40px;
    transform: rotate(-8deg);
  }
  .lg-pirmsskola-gregora-iela .ps-fig-2 {
    width: 320px;
    top: 38%;
    right: -70px;
    transform: rotate(10deg);
  }
  .lg-pirmsskola-gregora-iela .ps-fig-3 {
    width: 180px;
