  /* Sadarb&#299;ba ar &#291;imeni / &#274;diena kult&#363;ra sections */
  .lg-pirmsskola-adazos .ps-family,
  .lg-pirmsskola-adazos .ps-food {
    max-width: 980px;
    margin: 0 auto 64px;
    padding: 0 32px;
  }
  .lg-pirmsskola-adazos .ps-family .ps-schedule-heading,
  .lg-pirmsskola-adazos .ps-food .ps-schedule-heading {
