  /* Calendar placeholder section */
  .lg-pirmsskola-adazos .ps-calendar {
    max-width: 980px;
    margin: 0 auto 64px;
    padding: 0 32px;
  }
  .lg-pirmsskola-adazos .ps-calendar-heading {
    text-align: center;
