    padding: 48px 32px;
    min-height: 220px;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
  }
  .lg-pirmsskola-adazos .ps-calendar-icon {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: rgba(255, 144, 104, 0.15);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 26px;
