  .lg-pirmsskola-adazos .ps-contact-person {
    display: flex;
    align-items: center;
    gap: 20px;
    flex: 1 1 320px;
  }
  .lg-pirmsskola-adazos .ps-contact-portrait {
    width: 110px;
    height: 110px;
    border-radius: 50%;
    object-fit: cover;
    flex-shrink: 0;
    border: 2px solid rgba(255, 248, 238, 0.25);
