  .lg-pirmsskola-adazos .ps-contact-info h2 {
    color: var(--ps-cream);
    font-size: 24px;
    margin-bottom: 4px;
  }
  .lg-pirmsskola-adazos .ps-contact-role {
    font-size: 14px;
    color: rgba(255, 248, 238, 0.75);
    margin-bottom: 18px;
  }
  .lg-pirmsskola-adazos .ps-contact-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
