    }
    .lg-pirmsskola-adazos .ps-video-overlay-close {
      top: -40px;
    }
    .lg-pirmsskola-adazos .ps-approach-details {
      padding: 4px 20px;
    }
    .lg-pirmsskola-adazos .ps-activities-list {
