.lg-playlab {
    --green: #2A5E4A;
    --cream: #FFF8EE;
    --orange: #FF9068;
    --blue: #8E9DFF;
    --yellow: #F1B01D;
    --green-light: rgba(42,94,74,0.08);
  }

  .lg-playlab *, .lg-playlab *::before, .lg-playlab *::after { box-sizing: border-box; margin: 0; padding: 0; }

  .lg-playlab {
    background: var(--cream);
    color: var(--green);
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 17px;
    line-height: 1.55;
    overflow-x: hidden;
  }

  /* ---- HERO ---- */
  .lg-playlab .hero {
    background: var(--green);
    color: var(--cream);
    padding: 72px 40px 80px;
    position: relative;
    overflow: hidden;
  }

  .lg-playlab .hero-inner {
    max-width: 860px;
    margin: 0 auto;
    position: relative;
    z-index: 2;
  }

  .lg-playlab .eyebrow {
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--orange);
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 10px;
  }

  .lg-playlab .eyebrow::before {
    content: '';
    display: inline-block;
    width: 28px;
    height: 2px;
    background: var(--orange);
    flex-shrink: 0;
  }

  .lg-playlab .hero h1 {
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: clamp(48px, 8vw, 88px);
    font-weight: 700;
    line-height: 1.0;
    letter-spacing: -0.02em;
    color: var(--cream);
    margin-bottom: 28px;
  }

  .lg-playlab .hero h1 span {
    color: var(--orange);
  }

  .lg-playlab .hero-desc {
    font-size: 19px;
    line-height: 1.6;
    color: rgba(255,248,238,0.85);
    max-width: 580px;
    margin-bottom: 40px;
  }

  .lg-playlab .hero-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
  }

  .lg-playlab .pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    background: rgba(255,248,238,0.12);
    border: 1px solid rgba(255,248,238,0.25);
    color: var(--cream);
    border-radius: 100px;
    padding: 8px 18px;
    font-size: 14px;
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
  }

  .lg-playlab .pill svg { flex-shrink: 0; }

  /* decorative figures in hero */
  .lg-playlab .hero-deco {
    position: absolute;
    right: -30px;
    top: -20px;
    width: 340px;
    height: 340px;
    opacity: 0.09;
    pointer-events: none;
    z-index: 1;
  }

  .lg-playlab .hero-deco2 {
    position: absolute;
    left: -60px;
    bottom: -40px;
    width: 280px;
    height: 280px;
    opacity: 0.07;
    pointer-events: none;
    z-index: 1;
  }

  /* ---- SECTIONS ---- */
  .lg-playlab section { max-width: 860px; margin: 0 auto; padding: 64px 40px; }

  .lg-playlab .section-label {
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--orange);
    margin-bottom: 14px;
  }

  .lg-playlab h2 {
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: clamp(28px, 4vw, 40px);
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -0.01em;
    color: var(--green);
    margin-bottom: 20px;
  }

  .lg-playlab h3 {
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 20px;
    font-weight: 600;
    line-height: 1.2;
    color: var(--green);
    margin-bottom: 10px;
  }

  .lg-playlab p { line-height: 1.7; color: #2a3d34; }
  .lg-playlab p + p { margin-top: 14px; }

  /* ---- INTRO BLOCK ---- */
  .lg-playlab .intro-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 40px;
    margin-top: 36px;
  }

  .lg-playlab .intro-text { grid-column: 1 / -1; }

  @media (max-width: 640px) {
    .lg-playlab .intro-grid { grid-template-columns: 1fr; }
  }

  /* ---- FEATURE CARDS ---- */
  .lg-playlab .features-bg {
    background: var(--green);
  }

  .lg-playlab .features-bg section {
    padding-top: 72px;
    padding-bottom: 72px;
  }

  .lg-playlab .features-bg .section-label { color: var(--orange); }
  .lg-playlab .features-bg h2 { color: var(--cream); }

  .lg-playlab .cards {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 20px;
    margin-top: 40px;
  }

  .lg-playlab .card {
    background: rgba(255,248,238,0.07);
    border: 1px solid rgba(255,248,238,0.14);
    border-radius: 16px;
    padding: 28px 24px;
    color: var(--cream);
    transition: background 0.2s;
  }

  .lg-playlab .card:hover { background: rgba(255,248,238,0.12); }

  .lg-playlab .card-icon {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: var(--orange);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 18px;
    font-size: 20px;
  }

  .lg-playlab .card h3 { color: var(--cream) !important; margin-bottom: 8px; font-size: 17px; }
  .lg-playlab .card p, .lg-playlab .card p * { color: rgba(255,248,238,0.78) !important; font-size: 15px; line-height: 1.65; }
  .lg-playlab .features-bg p { color: rgba(255,248,238,0.78) !important; }

  /* ---- APPROACH BLOCKS ---- */
  .lg-playlab .approach-list { margin-top: 40px; display: flex; flex-direction: column; gap: 28px; }

  .lg-playlab .approach-item {
    display: grid;
    grid-template-columns: 52px 1fr;
    gap: 24px;
    align-items: flex-start;
    padding: 28px;
    background: white;
    border-radius: 16px;
    border: 1px solid rgba(42,94,74,0.1);
  }

  .lg-playlab .approach-num {
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: var(--cream);
    border: 2px solid var(--green);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 18px;
    font-weight: 700;
    color: var(--green);
    flex-shrink: 0;
  }

  /* color variants */
  .lg-playlab .approach-item:nth-child(2) .approach-num { background: var(--orange); color: white; border-color: var(--orange); }
  .lg-playlab .approach-item:nth-child(3) .approach-num { background: var(--blue); color: white; border-color: var(--blue); }
  .lg-playlab .approach-item:nth-child(4) .approach-num { background: var(--yellow); color: var(--green); border-color: var(--yellow); }

  /* ---- PRICE SECTION ---- */
  .lg-playlab .price-bg { background: var(--cream); }

  .lg-playlab .price-cards {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-top: 40px;
  }

  @media (max-width: 600px) {
    .lg-playlab .price-cards { grid-template-columns: 1fr; }
  }

  .lg-playlab .price-card {
    border-radius: 20px;
    padding: 36px 32px;
    position: relative;
    overflow: hidden;
  }

  .lg-playlab .price-card.main {
    background: var(--green);
    color: var(--cream);
  }

  .lg-playlab .price-card.alt {
    background: white;
    border: 1.5px solid rgba(42,94,74,0.18);
    color: var(--green);
  }

  .lg-playlab .price-tag {
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 48px;
    font-weight: 700;
    line-height: 1;
    margin: 16px 0 6px;
  }

  .lg-playlab .price-card.main .price-tag { color: var(--orange); }
  .lg-playlab .price-card.alt .price-tag { color: var(--green); }

  .lg-playlab .price-period { font-size: 15px; opacity: 0.7; margin-bottom: 20px; }

  .lg-playlab .price-card h3 { font-size: 18px; }
  .lg-playlab .price-card.main h3 { color: var(--cream); }

  .lg-playlab .price-note {
    font-size: 14px;
    line-height: 1.6;
  }

  .lg-playlab .price-card.main .price-note { color: rgba(255,248,238,0.72); }
  .lg-playlab .price-card.alt .price-note { color: #3d5a4e; }

  .lg-playlab .badge {
    position: absolute;
    top: 20px;
    right: 20px;
    background: var(--orange);
    color: white;
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 5px 12px;
    border-radius: 100px;
  }

  /* ---- IMPORTANT BOX ---- */
  .lg-playlab .info-box {
    background: rgba(241,176,29,0.12);
    border-left: 4px solid var(--yellow);
    border-radius: 0 12px 12px 0;
    padding: 24px 28px;
    margin-top: 32px;
  }

  .lg-playlab .info-box p { font-size: 15px; color: #2a3d34; }

  /* ---- CTA ---- */
  .lg-playlab .cta-bg { background: var(--orange); }

  .lg-playlab .cta-bg section {
    text-align: center;
    padding-top: 80px;
    padding-bottom: 80px;
  }

  .lg-playlab .cta-bg h2 { color: white; margin-bottom: 16px; }
  .lg-playlab .cta-bg p { color: rgba(255,255,255,0.88); font-size: 18px; max-width: 520px; margin: 0 auto 36px; }

  .lg-playlab .btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--green);
    color: var(--cream);
    text-decoration: none;
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
    font-size: 16px;
    font-weight: 600;
    padding: 16px 36px;
    border-radius: 100px;
    transition: opacity 0.15s, transform 0.15s;
  }

  .lg-playlab .btn:hover { opacity: 0.88; transform: translateY(-1px); }

  .lg-playlab .btn-outline {
    background: transparent;
    border: 2px solid white;
    color: white;
  }

  .lg-playlab .btn-outline:hover { background: rgba(255,255,255,0.12); }

  .lg-playlab .cta-buttons { display: flex; flex-wrap: wrap; gap: 14px; justify-content: center; }

  .lg-playlab .contact-line {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    color: rgba(255,255,255,0.72);
    font-size: 15px;
    margin-top: 28px;
    font-family: 'TT Norms Pro', 'Trebuchet MS', Arial, sans-serif;
  }

  /* ---- DIVIDER ---- */
  .lg-playlab .divider { border: none; border-top: 1px solid rgba(42,94,74,0.12); margin: 0; }

  /* ---- RESPONSIVE ---- */
  @media (max-width: 640px) {
    .lg-playlab .hero { padding: 56px 24px 64px; }
    .lg-playlab section { padding: 52px 24px; }
    .lg-playlab .hero-deco, .lg-playlab .hero-deco2 { display: none; }
    .lg-playlab .intro-grid { gap: 24px; }
    .lg-playlab .approach-item { grid-template-columns: 1fr; }
    .lg-playlab .approach-num { width: 40px; height: 40px; font-size: 15px; }
  }

