sections.css:
.lg-makslu-skola-muzika {
  --green: #2A5E4A;
  --cream: #FFF8EE;
  --gold:  #F1B01D;
}
.lg-makslu-skola-muzika .mu-page-wrapper {
  position: relative;
  background: var(--cream);
  overflow: visible;
  isolation: isolate;
}
.lg-makslu-skola-muzika .mu-figures-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: visible;
}
.lg-makslu-skola-muzika .mu-fig { position: absolute; opacity: 0.13; }
.lg-makslu-skola-muzika .mu-fig-anim-2 {
  width: 420px; top: -60px; left: -80px;
  transform: rotate(-18deg);
  animation: muFloat1 18s ease-in-out infinite;
}
.lg-makslu-skola-muzika .mu-fig-anim-5 {
  width: 340px; bottom: 40px; right: -60px;
  transform: rotate(12deg);
  animation: muFloat2 22s ease-in-out infinite;
}
.lg-makslu-skola-muzika .mu-fig-anim-6 {
  width: 300px; top: 45%; left: -40px;
  transform: rotate(5deg);
  animation: muFloat3 26s ease-in-out infinite;
}
.lg-makslu-skola-muzika .mu-fig-anim-1 {
  width: 260px; top: 120px; right: -70px;
  transform: rotate(20deg);
  animation: muFloat4 20s ease-in-out infinite;
}
@keyframes muFloat1 { 0%,100%{transform:rotate(-18deg) translateY(0)} 50%{transform:rotate(-14deg) translateY(18px)} }
@keyframes muFloat2 { 0%,100%{transform:rotate(12deg) translateY(0)} 50%{transform:rotate(8deg) translateY(-22px)} }
@keyframes muFloat3 { 0%,100%{transform:rotate(5deg) translateY(0)} 50%{transform:rotate(9deg) translateY(14px)} }
@keyframes muFloat4 { 0%,100%{transform:rotate(20deg) translateY(0)} 50%{transform:rotate(16deg) translateY(20px)} }
.lg-makslu-skola-muzika .mu-page {
  position: relative;
  z-index: 2;
  max-width: 860px;
  margin: 0 auto;
  padding: 5rem 3rem 6rem;
  font-family: 'Source Serif 4', Georgia, serif;
  color: var(--green);
}
.lg-makslu-skola-muzika .kp-label {
  display: inline-block;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--green);
  background: var(--gold);
  padding: 0.3rem 0.75rem;
  border-radius: 2px;
  margin-bottom: 2rem;
}
.lg-makslu-skola-muzika .mu-hero {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 2rem;
  align-items: center;
  margin-bottom: 3rem;
}
.lg-makslu-skola-muzika .mu-title {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(2.3rem, 4.5vw, 3.6rem);
  line-height: 1.03;
  letter-spacing: -0.03em;
  color: var(--green);
  margin: 0 0 1.5rem;
}
.lg-makslu-skola-muzika .mu-intro, .lg-makslu-skola-muzika .mu-page p {
  font-size: 1.05rem;
  line-height: 1.78;
  color: rgba(42,94,74,0.82);
}
.lg-makslu-skola-muzika .mu-btn {
  display: inline-block;
  margin-top: 1.4rem;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-decoration: none;
  color: var(--green) !important;
  background: var(--gold);
  padding: 0.85rem 1.25rem;
  border-radius: 4px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.lg-makslu-skola-muzika .mu-btn:hover { transform: translateY(-2px); box-shadow: 0 12px 28px rgba(42,94,74,0.16); }
.lg-makslu-skola-muzika .mu-btn.dark { background: var(--green); color: var(--cream) !important; }
.lg-makslu-skola-muzika .divider { width: 48px; height: 3px; background: var(--gold); border-radius: 2px; margin: 3rem 0; }
.lg-makslu-skola-muzika .mu-image {
  min-height: 320px;
  border: 2px dashed rgba(241,176,29,0.9);
  background: rgba(255,248,238,0.7);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.lg-makslu-skola-muzika .mu-image.mu-image-real {
  padding: 0;
  border: none;
  overflow: hidden;
}
.lg-makslu-skola-muzika .mu-image.mu-image-real img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 6px;
  display: block;
}
.lg-makslu-skola-muzika .mu-block { margin: 3rem 0; }
.lg-makslu-skola-muzika .mu-section-title {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(1.7rem, 3vw, 2.35rem);
  line-height: 1.08;
  letter-spacing: -0.025em;
  color: var(--green);
  margin: 0 0 0.5rem;
}
.lg-makslu-skola-muzika .mu-section-desc { color: rgba(42,94,74,0.6); margin-bottom: 1.5rem; font-size: 0.95rem; }
.lg-makslu-skola-muzika .choose-label {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(42,94,74,0.45);
  margin-bottom: 1.25rem;
}
.lg-makslu-skola-muzika .mu-instruments-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
}
.lg-makslu-skola-muzika .mu-instrument-item {
  background: var(--green);
  border-radius: 6px;
  padding: 1.25rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.lg-makslu-skola-muzika .mu-instrument-item:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(42,94,74,0.2); }
.lg-makslu-skola-muzika .mu-instrument-icon { font-size: 1.6rem; line-height: 1; }
.lg-makslu-skola-muzika .mu-instrument-item span {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: rgba(255,248,238,0.88);
  line-height: 1.3;
}
.lg-makslu-skola-muzika .mu-video-section {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 2.5rem;
  align-items: center;
  margin: 3rem 0;
}
.lg-makslu-skola-muzika .mu-video-text h2 {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(1.7rem, 3vw, 2.35rem);
  line-height: 1.08;
  letter-spacing: -0.025em;
  color: var(--green);
  margin: 0 0 1.2rem;
}
.lg-makslu-skola-muzika .mu-video-frame {
  border-radius: 8px;
  overflow: hidden;
  background: var(--green);
  aspect-ratio: 16/9;
}
.lg-makslu-skola-muzika .mu-pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}
.lg-makslu-skola-muzika .mu-price-card {
  background: white;
  border: 2px solid rgba(42,94,74,0.1);
  border-radius: 6px;
  padding: 1.75rem 1.5rem;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.lg-makslu-skola-muzika .mu-price-card:hover { transform: translateY(-2px); box-shadow: 0 10px 28px rgba(42,94,74,0.12); }
.lg-makslu-skola-muzika .mu-price-card.mu-price-main { background: var(--green); border-color: var(--green); }
.lg-makslu-skola-muzika .mu-price-tag {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-bottom: 0.6rem;
}
.lg-makslu-skola-muzika .mu-price-card.mu-price-main .mu-price-tag { color: rgba(255,248,238,0.5); }
.lg-makslu-skola-muzika .mu-price-card:not(.mu-price-main) .mu-price-tag { color: rgba(42,94,74,0.45); }
.lg-makslu-skola-muzika .mu-price-name {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: 1.1rem;
  margin-bottom: 1rem;
}
.lg-makslu-skola-muzika .mu-price-card.mu-price-main .mu-price-name { color: var(--cream); }
.lg-makslu-skola-muzika .mu-price-card:not(.mu-price-main) .mu-price-name { color: var(--green); }
.lg-makslu-skola-muzika .mu-price-amount {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: 2rem;
  letter-spacing: -0.02em;
}
.lg-makslu-skola-muzika .mu-price-amount span { font-size: 1rem; font-weight: 400; margin-left: 2px; }
.lg-makslu-skola-muzika .mu-price-card.mu-price-main .mu-price-amount { color: var(--gold); }
.lg-makslu-skola-muzika .mu-price-card:not(.mu-price-main) .mu-price-amount { color: var(--green); }
.lg-makslu-skola-muzika .mu-plan-list { display: flex; flex-direction: column; gap: 0.75rem; }
.lg-makslu-skola-muzika .mu-plan-item {
  background: white;
  border: 2px solid rgba(42,94,74,0.1);
  border-radius: 6px;
  overflow: hidden;
  transition: border-color 0.2s ease;
}
.lg-makslu-skola-muzika .mu-plan-item[open] { border-color: var(--gold); }
.lg-makslu-skola-muzika .mu-plan-summary {
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.15rem 1.5rem;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: 1rem;
  color: var(--green);
}
.lg-makslu-skola-muzika .mu-plan-summary::-webkit-details-marker { display: none; }
.lg-makslu-skola-muzika .mu-plan-summary::marker { content: ""; }
.lg-makslu-skola-muzika .mu-plan-icon {
  width: 26px; height: 26px; min-width: 26px;
  border-radius: 50%;
  background: var(--gold);
  position: relative;
}
.lg-makslu-skola-muzika .mu-plan-icon::before, .lg-makslu-skola-muzika .mu-plan-icon::after {
  content: "";
  position: absolute;
  background: var(--green);
  top: 50%; left: 50%;
  transform: translate(-50%,-50%);
  transition: opacity 0.2s ease;
}
.lg-makslu-skola-muzika .mu-plan-icon::before { width: 10px; height: 2px; }
.lg-makslu-skola-muzika .mu-plan-icon::after { width: 2px; height: 10px; }
.lg-makslu-skola-muzika .mu-plan-item[open] .mu-plan-icon::after { opacity: 0; }
.lg-makslu-skola-muzika .mu-plan-content { padding: 0 1.5rem 1.5rem; }
.lg-makslu-skola-muzika .mu-table-wrap { overflow-x: auto; }
.lg-makslu-skola-muzika .mu-plan-table {
  width: 100%;
  min-width: 640px;
  border-collapse: collapse;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 0.82rem;
}
.lg-makslu-skola-muzika .mu-plan-table th, .lg-makslu-skola-muzika .mu-plan-table td {
  padding: 0.55rem 0.6rem;
  text-align: center;
  border-bottom: 1px solid rgba(42,94,74,0.08);
  color: var(--green);
}
.lg-makslu-skola-muzika .mu-plan-table th {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700;
  color: rgba(42,94,74,0.5);
}
.lg-makslu-skola-muzika .mu-plan-table td:first-child, .lg-makslu-skola-muzika .mu-plan-table th:first-child { text-align: left; font-weight: 600; }
.lg-makslu-skola-muzika .mu-plan-table tr.mu-plan-total td { font-weight: 700; background: rgba(241,176,29,0.14); }
.lg-makslu-skola-muzika .mu-plan-note { margin-top: 1.25rem; font-size: 0.9rem; color: rgba(42,94,74,0.6); }
.lg-makslu-skola-muzika .mu-plan-note a { color: var(--green); font-weight: 700; text-decoration: underline; }
.lg-makslu-skola-muzika .mu-steps { display: flex; flex-direction: column; gap: 0; }
.lg-makslu-skola-muzika .mu-step {
  display: flex;
  gap: 1.25rem;
  align-items: flex-start;
  padding: 1.5rem 0;
  border-bottom: 1px solid rgba(42,94,74,0.1);
}
.lg-makslu-skola-muzika .mu-step:last-child { border-bottom: none; }
.lg-makslu-skola-muzika .mu-step-num {
  width: 40px; height: 40px; min-width: 40px;
  background: var(--gold);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: 1rem;
  color: var(--green);
}
.lg-makslu-skola-muzika .mu-step-text strong {
  display: block;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: 1rem;
  color: var(--green);
  margin-bottom: 0.3rem;
}
.lg-makslu-skola-muzika .mu-step-text p { margin: 0; font-size: 0.95rem; color: rgba(42,94,74,0.7); }
.lg-makslu-skola-muzika .mu-cta {
  background: var(--gold);
  border-radius: 6px;
  padding: 2.5rem;
  margin-top: 4rem;
}
.lg-makslu-skola-muzika .mu-cta h2 {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-weight: 700;
  font-size: clamp(1.7rem, 3vw, 2.35rem);
  line-height: 1.08;
  letter-spacing: -0.025em;
  color: var(--green);
  margin: 0 0 1rem;
}
.lg-makslu-skola-muzika .mu-cta p { color: rgba(42,94,74,0.78); max-width: 580px; margin-bottom: 0; }
@media (max-width: 700px) {
  .lg-makslu-skola-muzika .mu-page { padding: 3rem 1.5rem 4rem; }
  .lg-makslu-skola-muzika .mu-hero, .lg-makslu-skola-muzika .mu-video-section, .lg-makslu-skola-muzika .mu-pricing-grid { grid-template-columns: 1fr; }
  .lg-makslu-skola-muzika .mu-instruments-grid { grid-template-columns: repeat(2, 1fr); }
  .lg-makslu-skola-muzika .mu-fig { opacity: 0.1; }
  .lg-makslu-skola-muzika .mu-fig-anim-2 { width: 260px; left: -130px; top: -70px; }
  .lg-makslu-skola-muzika .mu-fig-anim-5 { width: 230px; right: -120px; bottom: 140px; }
  .lg-makslu-skola-muzika .mu-fig-anim-6 { width: 210px; left: -125px; top: 55%; }
  .lg-makslu-skola-muzika .mu-fig-anim-1 { width: 180px; right: -90px; top: 100px; }
}
